quests[30265] = { id = 30265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Funkeln im Auge", description = "Ich habe lange in das Wasser geblickt und über das Leben, die Liebe und all die schönen Dinge sinniert, als ich plötzlich ein Glitzern im Wasser bemerkte. Und das waren nicht etwa die Reflexionen meiner strahlenden Persönlichkeit, sondern tatsächlich ein paar glitzernde Objekte da unten! Sicher etwas Wertvolles.\n\nWürdet Ihr vielleicht in die Tiefen hinabtauchen, um den See seiner glitzernden Geheimnisse zu berauben? Oh, bitte!", sourceObjective = "Bergt 8 Glitzerrubine.", progress = "Und? Was war dieses mysteriöse Glitzern? Ich sterbe vor Neugierde. Münzen? Pokale? Ein Dutzend entsorgter Hochzeitsringe?", completion = "Rubine! Und zwar sehr wertvolle! Und vielleicht steckt dahinter eine interessante Geschichte mit einem Dutzend Bräuten mit gebrochenen Herzen? Wahrscheinlich nicht. Aber trotzdem ein aufregender Fund!\n\nIch danke Euch von ganzem Herzen, mein großzügiger Freund! Mit Euren aquatischen Fähigkeiten habt Ihr meine Garderobe davor bewahrt, ganz fürchterlich nass zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30266] = { id = 30266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmel voller Blut", description = "Wir haben im oberen Bereich der Türme an den Flanken des Haupttors Kanonen platziert. Sie sind unsere beste Waffe, um die fliegenden Mantis daran zu hindern, die Mauer zu überfliegen. Und genau das versuchen sie gerade wieder.\n\nIch glaube, Ihr seid nun an der Reihe, {name}.", sourceObjective = "Tötet 30 Drohnen der Krik'thik mit einer Kanone am Tor der Untergehenden Sonne.", completion = "Eure Schützentalente sind beachtlich, {class}. Daran werde ich mich erinnern, wenn sich wieder einmal Feinde aus der Luft nähern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30267] = { id = 30267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglerträume", description = "Ich liebe es zu angeln. Der Spaß wäre jedoch wesentlich größer, wenn ich meine Köder hätte. Die hat aber meine Frau Rin wegen eines... eines Missverständnisses weggeworfen.\n\n<Lichtungswirker Lang seufzt.>\n\nSoll etwa ein ganzer Angeltag wegen einer winzigen ehelichen Meinungsverschiedenheit verdorben sein? Nein! Alles, was ich brauche, sind ein paar Insekten und Federn - und diese Lichtung ist voll von beidem.\n\nWürdet Ihr einem Angler vielleicht helfen?", sourceObjective = "Besorgt 18 Lichtungsglühwürmer und 5 spindeldürre Blutfedern.", progress = "Ich sehe es nicht ein, auf das Angeln zu verzichten. Das ist mein Leben!", completion = "Endlich jemand, der mich versteht. Angeln ist doch das Einzige, was zählt, oder?\n\nVielleicht sollte ich Neu-Cifera verlassen... Einfach meinen Kram packen und mich den Anglern unten im Süden anschließen. Natürlich könnte ich meine Familie nicht zurücklassen...\n\nAber trotzdem... Ein Pandaren kann doch auch mal träumen, stimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[30268] = { id = 30268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Düsterfieber", description = "Seht genau hin. Der Fluss in der Nähe wimmelt von diesen Schlangen. Ihr Gift führt zu einem Zustand, den die Einheimischen \"das Düsterfieber\" nennen.\n\nEin paar Flüchtlinge wurden gebissen, als sie aus dem Tempel flohen, und zeigen bereits erste Symptome: Übelkeit, Erbrechen und Schweißausbrüche. Der Körper scheidet jegliche Flüssigkeit aus, was zu Dehydrierung und möglicherweise zum Tod führt.\n\nWir verabreichen so schnell wie möglich Gegengift, aber wir brauchen noch mehr Giftdrüsen. Haltet Euch nicht damit auf, die Drüsen selbst zu entfernen - bringt einfach den ganzen Kopf mit.", sourceObjective = "Sammelt 6 Düsterschuppenköpfe von Angreifern der Düsterschuppen im Krasarang.", progress = "<Anduin konzentriert sich aufmerksam auf seine Hände und schneidet schnell die Giftdrüsen aus den Schlangen.>\n\nIm Rachen... fünf Zentimeter hinter der zweiten Reihe Fangzähne...", completion = "Danke, {class}. Ich wusste, dass Ihr zäh genug seid, um damit fertigzuwerden.\n\nWenn ich mir so die Geräusche anhöre, die diese Flüchtlinge von sich geben, würde ich das Düsterfieber nicht meinem ärgsten Feind wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30269] = { id = 30269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichere Passage", description = "Wie wir im Tempel immer sagen: \"Kämpft nie gegen einen Tiger, wenn Ihr einen Ho-zen im Nacken habt.\"\n\nWir werden uns um das Sha kümmern, aber zunächst muss unsere Aufmerksamkeit der unmittelbaren... Plage gelten.\n\n<Koro schleudert den sich krümmenden Saurok HART gegen den Felsen.>\n\nFlüchtlingsgruppen aus dem Tempel sind auf dem Weg zu einem Lager im Norden, doch sie werden von Saurok angegriffen. Helft mir, die nächste Gruppe zum Lager zu bringen, dann entscheiden wir über unser weiteres Vorgehen.", sourceObjective = "Helft Koro Nebelgänger, eine Gruppe Flüchtlinge vom Tempel des Roten Kranichs zum Refugium der Kranichschwingen zu eskortieren. Sprecht vor Beginn zuerst mit Koro.", completion = "Danke, {name}. Ohne Eure Hilfe hätten wir es nicht geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30270] = { id = 30270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blenden der Flussklingen", description = "\"Ein Falke mit Kappe fängt keine Beute.\"\n\nDas ist eines der ersten Mantras, die wir jungen Mönchen im Tempel beibringen. Es bedeutet, dass sogar ein Gegner, der so schnell und tödlich wie ein Falke ist, neutralisiert werden kann, indem man ihn seiner Sinne beraubt.\n\nDie Saurok verfügen in der ganzen Region über Späher, die ihren Raubzügen als Augen dienen.\n\nEs wird Zeit, dass wir ihnen die Augen ausstechen, meint Ihr nicht auch?\"", sourceObjective = "Tötet 8 Wegelagerer der Flussklingen in der Umgebung des Refugiums der Kranichschwingen.", completion = "Gut gemacht. Ich wünschte nur, ich hätte Euch begleiten können...\n\nDas Blut auf diesen Handlappen ist nicht mein eigenes, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[30271] = { id = 30271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shapokalypse", sourceObjective = "Tötet Sha in der Nähe von 10 hoffnungslosen Mönchen oder Akolythen, um sie zu inspirieren.", progress = "Haltet nach Kranichschwingen-Pandaren Ausschau, die der Verzweiflung anheimfallen, und erschlagt Sha in ihrer Nähe, während ich Euch unterstütze!", completion = "Ehrlich gesagt bin ich ein wenig überrascht, dass das funktioniert hat.\n\nPandaria erweist sich als Land, in dem die Grenze zwischen Metapher und Realität verschwommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30272] = { id = 30272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regen schlagen", description = "Was den Teil \"auf den Regen einschlagen\" angeht... Nun, manchmal muss man es einfach tun.\n\n\"Hoffnung ist die Sonne jenseits eines stürmischen Himmels - stets im Herzen, aber dem Auge verborgen.\"\n\nDas aus dem Tempel strömende Sha scheint kein Ende zu nehmen. Aber um hinter den Schleier der Verzweiflung zu sehen, müsst Ihr ihn zerschneiden.\n\nMit ein wenig Glück findet Ihr hinter den Wolken den Sonnenschein...", sourceObjective = "Tötet 18 Spuke der Verzweiflung beim Tempel des Roten Kranichs.", completion = "Wisst Ihr was, {name}? Wir geben ein ziemlich gutes Team ab!", sourceObjectiveStatus = "unverified-source-field" }
quests[30273] = { id = 30273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Haus des Roten Kranichs", sourceObjective = "Begebt Euch in den Keller des Tempels des Roten Kranichs und besiegt das Sha der Verzweiflung.", completion = "Ihr habt das Sha der Verzweiflung bezwungen. Mein Orden wird sich darum kümmern, hier aufzuräumen.\n\nWie es scheint, ist die Zeit gekommen, sich den Konsequenzen von Shaohaos Entscheidungen zu stellen.\n\nDieser Konflikt hat sich über Jahrtausende hinweg angebahnt - die Ankunft Eures Volkes war lediglich der Stein, der die Lawine ins Rollen gebracht hat. Wie dem auch sei, Eure Hilfe wird nötig sein, wenn Pandaria überleben soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[30274] = { id = 30274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die arkane Oubliette", description = "Ein Mitglied der Allianz? Hier? Elune sei gepriesen.\n\nMein Trupp ist auf ein Hindernis gestoßen. Wir haben mit ein paar alten Texten, die wir auf die Zeit vor Azsharas Herrschaft datiert haben, ein Portal zu diesem Land geöffnet.\n\nUnglücklicherweise waren die Koordinaten auf den Tafeln geschützt, und so lieferte uns das Portal, das uns zu unserem Ziel bringen sollte, in dieser Oubliette ab.\n\nWir sind hier schon seit Tagen gefangen, und das Portal zehrt langsam an unserer Energie, um sich selbst zu versorgen.\n\nKönnt Ihr die Fesseln in der Nähe suchen, die die Oubliette binden, und sie deaktivieren?", sourceObjective = "Sucht und deaktiviert 3 Fesseln der Oubliette.", completion = "Fabelhaft! Euer Zeitgefühl war einwandfrei. Noch ein Tag da drin und wir hätten uns wahrscheinlich in Nichts aufgelöst.\n\nJetzt können wir unsere Suche nach den Teichen der Jugend fortsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30275] = { id = 30275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantismus", description = "Wie konnte dieser Krokilisk so groß werden?\n\nKlar, es gibt Gerüchte von sehr alten Krokilisken, die zu einer enormen Größe wachsen... aber dieses Weibchen ist höchstens 12 Jahre alt.\n\nVielleicht kann jemand in Neu-Cifera mehr über die Sache herausfinden.", sourceObjective = "Bringt den riesigen Krokiliskenschwanz zu Yan in Neu-Cifera im Tal der Vier Winde.", progress = "Was habt Ihr denn da?", completion = "Dieser Schwanz stammt von einem Krokilisken? Seltsam, soweit flussaufwärts gibt es nicht besonders viele Krokis.\n\nIst Euch das gigantische Obst und Gemüse aufgefallen, das unsere Bauern anpflanzen? Dieser Krokilisk ist aus dem gleichen Grund so groß geworden - es ist irgendetwas im Wasser.\n\nWas das ist, wissen wir nicht... aber wir sehen es als ein großes Glück an. Riesiges Gemüse ist eine tolle Sache. Ein riesiger Krokilisk dann und wann ist bloß eine Nebenerscheinung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30277] = { id = 30277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bröckelnde Halle", description = "In den Guo-Lai-Hallen wurde jenseits der Statuenhalle ein uraltes Moguartefakt entdeckt. Wir haben schon mehrfach versucht, das Artefakt zu bergen, hatten aber bisher keinen Erfolg.\n\nDieses Artefakt darf auf keinen Fall in die Hände der Shao-Tien fallen. Jemand muss dieses Artefakt bergen - und zwar schnell.\n\nKann ich auf Euch zählen?", sourceObjective = "Bergt das uralte Guo-Lai-Artefakt.", progress = "Habt Ihr das Artefakt schon bergen können?", completion = "Wenn alle anderen scheitern, seid Ihr zur Stelle. Das gefällt mir so an Euch.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30278] = { id = 30278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30279] = { id = 30279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30280] = { id = 30280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Röhren aus der Tiefe", description = "Aus den Guo-Lai-Hallen dringt ein mächtiges Röhren. Die Mogu haben dort irgendeine uralte Bestie zum Leben erweckt. Und sie werden sie wohl schon bald auf meine Männer loslassen.\n\nIch möchte, dass Ihr in die Halle der Schlange eindringt und diese Bestie unschädlich macht, bevor die Mogu sie gegen uns einsetzen. Mit einer solch gefährlichen und bedeutenden Aufgabe kann ich niemanden außer Euch beauftragen.", sourceObjective = "Tötet Milau.", completion = "Euch ist gelungen, was selbst mir kaum möglich gewesen wäre. Demütig zolle ich Eurer Stärke Respekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30281] = { id = 30281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leises Anschleichen", description = "<Er lehnt sich vor und zeichnet etwas, was nur einen Mogu darstellen kann, zeigt in Richtung des Sees im Westen, zieht die stumpfe Seite seines Dolches über seine Kehle und schaut Euch erwartungsvoll an. Es scheint, als wolle er, dass Ihr die Mogu am Weißblütensee tötet.>", sourceObjective = "Tötet 6 Shao-Tien-Mogu am Weißblütensee.", completion = "Die Anzahl der Mogu scheint ausreichend reduziert zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30282] = { id = 30282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Dreck wegbrennen", description = "Die Mogu haben ihre dreckigen Banner rund um den See im Westen gehisst, um dieses Gebiet als ihr Territorium zu markieren. Nehmt diese Fackel und zeigt ihnen, was wir von ihren Bannern halten.", sourceObjective = "Verbrennt 10 Shao-Tien-Banner.", completion = "Ich gehe davon aus, dass der Rauch am Horizont bedeutet, dass die Mogu die Botschaft erhalten haben. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[30283] = { id = 30283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagende Argumente", description = "Manchmal tun mir diese Mogu nachgerade leid... Vielleicht reißen sie anderen Völkern nur deshalb die Seelen heraus, weil sie selbst Probleme mit ihren Familien zu Hause haben? Vielleicht sollten wir mehr Verständnis für den Ursprung ihrer Gewaltbereitschaft aufbringen?\n\nOder wir zerschlagen einfach ihre seelenraubenden Ritualobjekte da unten am See. Das würde mir persönlich ja viel mehr Spaß bringen.", sourceObjective = "Zerstört die Shao-Tien-Ritualstatuen.", completion = "Wenn mich irgendjemand fragt, welcher Unhold denn ihre kleinen Statuetten kaputt gemacht hat, werde ich auf Euch verweisen.\n\nAber ich weiß Eure Hilfe natürlich trotzdem zu schätzen. Wirklich sehr liebenswert.", sourceObjectiveStatus = "unverified-source-field" }
quests[30284] = { id = 30284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausend spitze Zähnchen", description = "Das Wasser hat heute vor Gefahren nur so gebrodelt! Eine Art schwärmende, fleischfressende Fischpest hat sich in unserem See breitgemacht! Ein abscheulicher Anblick. Und das, wo ich gerade dabei war, mich vollständig zu entkleiden, um mich meinen täglichen Wasserübungen hinzugeben!\n\nIhr seid doch geübt darin, alle möglichen Kreaturen zu entsorgen, nicht wahr? Würdet Ihr also vielleicht so freundlich sein, Eure Fertigkeiten zu nutzen, um allen schwimmbegeisterten Pandaren einen Gefallen zu tun?\n\nDas wäre eine wirklich noble Tat für die Allgemeinheit - und insbesondere für mich.", sourceObjective = "Tötet 9 Messerzahnschwärmer.", completion = "Ihr seid aber auch wirklich zu freundlich! Ich habe tatsächlich Gefallen an Euch gefunden.\n\nUnd jetzt werde ich mich wieder dem Wassertreten widmen. Ich werde mich beherrschen und meine Garderobe erst ablegen, wenn Ihr Euch entfernt habt. Sozusagen als Entgegenkommen für Eure Freundlichkeit.\n\nAuch wenn Euch dadurch ein famoser Anblick entgeht...", sourceObjectiveStatus = "unverified-source-field" }
quests[30285] = { id = 30285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherberichte der Wukao", description = "Nach dem Angriff sind einige Späherberichte da draußen geblieben, die wir noch nicht eingesehen haben. Mit etwas Glück befinden sie sich noch im Dorf, aber vielleicht sind sie auch schon den Mogu in die Hände gefallen.\n\nWenn Ihr mir alle Späherberichte zurückbringt, die Ihr finden könnt, würdet Ihr mir einen großen Gefallen tun. Die Mogu dürfen nichts über unsere Stellungen oder unsere gefundenen Artefakte erfahren. Dann wären nämlich die Männer in einer noch viel größeren Gefahr.", sourceObjective = "Holt 3 Wukaospäherberichte.", progress = "Habt Ihr die Berichte finden können? Ich mache mir Sorgen um die Sicherheit meiner Männer im Feld, wenn sie in die Hände der Mogu fallen.", completion = "Ihr seid sehr freundlich, {name}. Ich bin jetzt wirklich sehr, sehr erleichtert.", sourceObjectiveStatus = "unverified-source-field" }
quests[30286] = { id = 30286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Enge getrieben", description = "Viele Dorfbewohner sind verängstigt und in die Enge getrieben. Ihr müsst ihnen zu Hilfe eilen und sie beschützen.\n\nBitte beeilt Euch und rettet so viele von ihnen wie möglich!", sourceObjective = "Rettet 6 in die Enge getriebene Dorfbewohner von Nebelhauch.", completion = "Wir haben alle, die wir gefunden haben, in der Schenke versammelt. Ab jetzt sollten wir sie selbst beschützen können.\n\nDanke wieder einmal für Eure Hilfe, {name}. Ihr scheint immer zur Stelle zu sein, wenn wir Eure Hilfe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30287] = { id = 30287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu keine guten Gäste", description = "Leven hat Rook hierher geschickt, um Mogu aufzuhalten. Sind aber mehr Mogu als Rook töten kann.\n\nHelft Ihr? Rook erzählt Leven auch von Eurer Hilfe. Versprochen.", sourceObjective = "Tötet 6 Shao-Tien-Angreifer in Nebelhauch.", progress = "Immer noch viele Mogu. Bitte helft Rook.", completion = "Rook kommt jetzt mit restlichen Mogu klar. Danke für Hilfe, guter Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[30288] = { id = 30288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es brennt... schon wieder!", description = "Ich weiß nicht, ob Ihr es bemerkt habt, aber meine Stadt brennt... schon wieder.\n\nWir haben überall Wassereimer im Ort, aber niemanden, der die Feuer löschen kann. Bitte helft uns!", sourceObjective = "Nutzt die Wassereimer in Nebelhauch, um 60 Feuer zu löschen.", progress = "Wir haben schon unser Zuhause am Kun-Lai verloren! Dieses hier dürfen wir nicht auch noch verlieren!", completion = "Ich wünschte, Ihr würdet damit aufhören, auch die Eimer ins Feuer zu schmeißen... das Wasser an sich würde schon ausreichen.\n\nAber ganz im Ernst, was für eine Erleichterung, dass Ihr hier seid, um zu helfen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30289] = { id = 30289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung der gestohlenen Seelen", description = "Mogu stehlen Seelen von Leuten! Lassen sie böse Dinge tun.\n\nAber nicht die Leute töten, sondern die Mogu. Dann vergessen die Leute die Verstandklauerei der Mogu und machen keine bösen Dinge mehr. Ihr solltet den Leuten helfen. So wie Rook.", sourceObjective = "Befreit 6 besessene Wachen, indem Ihr die Mogu tötet, die deren Gedanken steuern.", completion = "Viele Dorfbewohner jetzt drinnen und in Sicherheit. Ihr habt gute Arbeit gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30290] = { id = 30290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steingebundene Mörder", description = "Mogusteinhundkreaturen jagen Dorfbewohner und tun ihnen weh. Rook wollte sie zerschmettern. Aber sie sind zu schnell.\n\nKönnt Ihr helfen und auch welche zerschmettern?", sourceObjective = "Tötet 8 steingebundene Qilen.", completion = "Ja! Ihr seid schneller als Rook. Gute Arbeit gemacht!\n\nDanke, guter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[30291] = { id = 30291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betäubende Effizienz", description = "Ich habe mit dem guten Tantan hier gesprochen... Wieder und wieder... Und er besteht darauf, dass das Angeln eine erhebende Freizeitgestaltung darstelle. Und trotz meiner gebotenen Skepsis habe ich es noch einmal versucht. Aber da ich kein Freund davon bin, einen Stock in das Wasser zu halten und eine Ewigkeit zu warten, habe ich mich an einer etwas direkteren Methode versucht.\n\nWürdet Ihr vielleicht so liebenswürdig sein und alle Fische einsammeln, die zwar mit dem Bauch nach oben im Wasser treiben, aber gleichwohl vollkommen intakt sind?", sourceObjective = "Sammelt 12 betäubte Weißblütenkarpfen ein.", progress = "Ein weiterer Vorteil meiner Methode ist der Umstand, dass sie schon gekocht sind! Das nenne ich Effizienz in Reinkultur!", completion = "Wundervoll! Eure Einsammelfähigkeiten sind wirklich beachtlich.\n\nUnd ich bin auch dankbar dafür, dass Ihr Euch nicht zu schade wart, Euch Eure schicke Rüstung nass zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30292] = { id = 30292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böses Erwachen", description = "Die Mogu haben die Kontrolle über die Seelen der Saurok am See im Westen übernommen und hetzen sie gegen uns auf! Allerdings waren die Saurok schon vorher unsere Feinde. Ich weiß also nicht, ob sie das Ganze so besonders gut durchdacht haben...\n\nAuf jeden Fall ist ja Anji mehr die Kämpferin von uns beiden - und ich mehr der Liebhaber. Ich suche also jemanden, der die Waffen schwingt, Zaubersprüche loslässt und Kriegsgeheul ausstößt und so. Mit anderen Worten: Könntet Ihr ein paar Saurok für mich töten?", sourceObjective = "Tötet 8 besessene Fleischfresser der Bleichklingen.", completion = "Ihr riecht nach Saurok und Mogu. Keine allzu schöne Kombination, mein Bester. Aber es lässt darauf schließen, dass Ihr die Aufgabe erledigt habt. Vielen Dank also.\n\nVielleicht treffen wir uns ja bald mal wieder - unter geruchlich besseren Bedingungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30293] = { id = 30293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Hand des Feindes", description = "Die Geistbeuger der Shao-Tien haben die Kontrolle über den Verstand unserer Verteidiger am Weißblütensee im Westen übernommen. Ich möchte, dass Ihr Euch dorthin begebt und die Mogu tötet, die unsere Verteidiger kontrollieren. Aber unsere Leute dürfen nicht zu Schaden kommen! Wenn die Feinde getötet werden, werden auch die Geister der Verteidiger wieder befreit.\n\nIhr solltet Euch beeilen, denn Anji könnte auf die Idee kommen, sich auch dort einzufinden und zu helfen. Aber ihre Fähigkeit, sich in der Hitze des Kampfs zurückzuhalten, gehört nicht zu den Qualitäten, aufgrund derer ich sie geheiratet habe.", sourceObjective = "Setzt 8 besessenen Weißblütenverteidigern zu, bis sie von der Gedankenkontrolle der Mogu befreit sind.", completion = "Heute wird Euch ganz sicher mehr als nur ein Pandaren für Eure Hilfe dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30294] = { id = 30294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleiner Trost", description = "Die Geistbeuger am Weißblütensee berauben die Toten ihrer Seelen, um sie irgendwelchen fürchterlichen Qualen zu unterziehen.\n\nIch habe auf dieser Schriftrolle einen Ritus niedergeschrieben, der die Seelen von den Körpern befreit und sie auf den richtigen Weg geleitet. Wohin dann ihre Reise führt und was mit ihnen dann geschieht, weiß ich nicht, aber wenigstens sind sie so in Sicherheit vor den grausamen Mogu.\n\nLest diesen Ritus bei jedem Gefallenen, den Ihr findet. Wir werden ihre Leichen dann später bergen.", sourceObjective = "Lest den Ritus der Befreiung 6 gefallenen Verteidigern des Goldenen Lotus vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[30295] = { id = 30295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn-in Quest Test Case" }
quests[30296] = { id = 30296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaohun der Seelenschnitter", description = "Großer Moguanführer ist da! Gleich hinter dem Dorf. Wenn wir großen Moguanführer töten können, Leven wird stolz auf uns sein!\n\nIhr habt Rook schon gut geholfen. Vielleicht Ihr helft mir noch mal? Bitte?", sourceObjective = "Tötet Gaohun den Seelenschnitter.", completion = "Anführer weg. Leute sicher. Rook hat Dorf gerettet. Guter Freund hat auch Dorf gerettet. Rook sagt danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[30297] = { id = 30297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baolai der Verbrenner", description = "Großer Moguanführer ist da! Gleich hinter dem Dorf. Wenn wir großen Moguanführer töten können, Leven wird stolz auf uns sein!\n\nIhr habt Rook schon gut geholfen. Vielleicht Ihr helft mir noch mal? Bitte?", sourceObjective = "Tötet Baolai den Verbrenner.", completion = "Anführer weg. Leute sicher. Rook hat Dorf gerettet. Guter Freund hat auch Dorf gerettet. Rook sagt danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[30298] = { id = 30298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen in Blut tränken", description = "Die Mogu denken, sie können diese Ruinen ungeschoren übernehmen. Wir wollen ihnen zeigen, dass sie sich irren.", sourceObjective = "Tötet 8 Mogu in den Guo-Lai-Ruinen.", completion = "Ihre Stellung in diesen Ruinen wird keinen Bestand haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30299] = { id = 30299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Stein auf dem anderen lassen", description = "Die Mogu haben Seelen mit Gewalt in alte Statuen verpflanzt, um sie zum Leben zu erwecken, zu kontrollieren und sie gegen uns einzusetzen.\n\nDiese gebundenen Geister können nur befreit werden, indem man ihre Behältnisse zerstört.", sourceObjective = "Zerstört 6 Mogustatuen.", completion = "Nur dank Eurer Mühen können wir der Situation hier standhalten. Ich danke Euch vielmals für Eure Hilfe, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[30300] = { id = 30300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zum Erfolg", description = "Die Mogu haben Gefangene genommen. Sie werden sie foltern oder ihnen noch schlimmeres Leid zufügen.\n\nBitte tut alles dafür, sie aus ihren Käfigen zu befreien.", sourceObjective = "Findet den Shao-Tien-Käfigschlüssel und befreit 6 Gefangene des Goldenen Lotus.", progress = "Ich wäre lieber tot als ein Gefangener der Mogu zu sein. Sie sind äußerst grausam zu ihren Gefangenen.", completion = "Viele der von Euch befreiten Gefangenen sind jetzt hier im Lager, um sich zu erholen. Ihre - und meine - Dankbarkeit ist Euch gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[30301] = { id = 30301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein warmer Willkommensgruß", description = "Die Zelte niederzubrennen, in denen sie schlafen, sollte ihnen eine deutliche Botschaft sein.\n\nDurchkämmt die Ruinen und zerstört jedes einzelne ihrer Zelte.", sourceObjective = "Verbrennt 6 Moguzelte in den Guo-Lai-Ruinen.", completion = "Der Rauch in der Ferne zeugt von Eurem Erfolg. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30302] = { id = 30302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Imperion-Bedrohung", description = "Die Späher haben gesehen, dass ein Shao-Tien-Imperion die Guo-Lai-Hallen betreten hat. Ich brauche jemanden, bei dem ich mich darauf verlassen kann, dass dieser Anführer die Hallen nicht wieder lebend verlässt.\n\nUnd ich denke, Ihr habt genau die richtigen Qualitäten für diese Aufgabe, {class}.", sourceObjective = "Tötet den Shao-Tien-Imperion.", progress = "Die Mogu haben wiederholt Gruppen ihrer stärkeren Krieger in diese Kammern geschickt. Da drinnen ist definitiv etwas, das sie haben wollen.", completion = "Ihr habt mich nicht hängen lassen. Ich werde das nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30304] = { id = 30304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hart wie ein Stein", description = "Hey! Wisst Ihr, was das Beste war, das mir heute Morgen passiert ist?\n\nIch bin mit Anji in den Ruinen spazieren gegangen und hatte meinen Blick auf den Boden gerichtet, um nicht über einen dieser ekligen Spinnensäcke zu stolpern. Und dann ist auf einmal eine der Statuen zu Leben erwacht und hat versucht, mich in Grund und Boden zu stampfen!\n\nAnji hat sie dann aber selbst in Grund und Boden gestampft. Aber das langt mir noch nicht. Ich glaube, Ihr solltet da raus gehen und alle Statuen zerschmettern - ganz gleich ob sie am Leben sind oder nicht. Das ist die einzige Möglichkeit, für absolute Sicherheit zu sorgen.", sourceObjective = "Zerstört 10 Mogustatuen.", completion = "Ich bin Euch für Eure Ruinenzerstörungsaktion aufrichtig dankbar, mein Bester.", sourceObjectiveStatus = "unverified-source-field" }
quests[30305] = { id = 30305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er weiß, was er tut", description = "Ihr kennt Hee Samtfuß? Komischer Kerl, redet nicht viel. Stellt überall in den Ruinen Fallen auf für die Mogu. Sagte, dass Rook die Mogu nur in die Fallen locken muss. Aber weiß nicht wie.\n\nVielleicht könnt Ihr das machen? Fallen finden und die bösen Jungs reinlocken? Aber bitte Hee nichts davon erzählen, ja?", sourceObjective = "Lockt 8 Feinde in Hees Giftfallen.", progress = "Ihr macht doch diese Fallensache für Rook, ja? Bitte?", completion = "Ihr seid wirklich guter Freund. Rook mag Euch. Danke, guter Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[30306] = { id = 30306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampfring", description = "Wir haben ein paar neue Auszubildende, die Euch zwar nicht einzeln, aber vielleicht als Gruppe gefährlich werden könnten. Und wenn nicht, erfahren sie eben eine Lektion in Demut.\n\nSteigt in den Ring, wenn Ihr bereit seid. Und macht es ihnen nicht zu leicht.", sourceObjective = "Besiegt 20 Shado-Pan-Auszubildende im Kampfring.", progress = "Steigt in den Ring. Zeigt ihnen, wie ein echter {class} kämpft.", completion = "Sehr beeindruckend. Die anderen scheinen noch viel lernen zu müssen. Aber dafür werde ich schon sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30307] = { id = 30307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ewige Wacht", description = "Gut, Euch an unserer Seite zu wissen, {class}. Wenn Ihr in den Kampf eintreten wollt, könnte ich mehr Kämpfer oben bei der goldenen Treppe gebrauchen, um die Mogu auszuschalten, die dort eine Basis errichten wollen.\n\nKann ich auf Euch zählen?", sourceObjective = "Tötet 8 Mogu der Shao-Tien auf der Goldenen Terrasse.", completion = "Wir werden diese Linie halten. Egal, wie lange ihr Ansturm dauert - wir werden die Linie halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30308] = { id = 30308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinharte Qilen", description = "Leven sagt immer, dass nur tote Qilen gute Qilen seien. Und ich würde ihm zustimmen. Seid Ihr hier, um uns zu helfen?", sourceObjective = "Tötet 6 Granitqilen.", completion = "Weniger von diesen Bestien auf dem Schlachtfeld versüßen mir immer ein bisschen den Tag. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30309] = { id = 30309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stein gemeißelt", description = "Die Mogu haben heute ihre eitlen Steineffigien auf das Schlachtfeld geschickt. Sie erwecken sie oben auf der Goldenen Treppe zum Leben.\n\nJe größer sie sind, desto härter müssen wir sie treffen. Seid Ihr dabei?", sourceObjective = "Zerstört 6 Mogueffigien.", completion = "Auf dem Schlachtfeld ist heute eine zufriedenstellende Menge Geröll zu sehen. Ein Zeichen Eurer guten Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30310] = { id = 30310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giganten der Lüfte", description = "Die Mogu haben den Willen der Himmelsschlangen gebrochen und sie gegen uns eingesetzt.\n\nDie Verteidiger haben ihnen nicht viel entgegenzusetzen, aber Ihr vielleicht schon. Begebt Euch in Richtung Nordwesten, zur Goldenen Treppe, und wischt sie vom Himmel.", sourceObjective = "Tötet 3 bezwungene Schlangen.", completion = "Was für ein Kampf! Ich glaube, Eure Vorstellung hat sogar die Moral der Truppe etwas gehoben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30311] = { id = 30311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehobene Standarte", description = "Meiner Meinung nach ist die vornehmste Qualität einer Kampfstandarte ihre Eigenschaft, aufgerichtet zu stehen... und nicht zu brennen. Und genau aus diesem Grund bereitet mir unsere Standartensituation gerade Verdruss.\n\nWenn sich also <ein unbekannter/eine unbekannte:c> {class} finden lassen könnte, die Standarten auf dem Schlachtfeld im Nordwesten wieder aufzurichten, wären ich und meine ungemein attraktive - wenngleich auch etwas herrische - Frau äußerst dankbar.", sourceObjective = "Richtet 6 Standarten des Goldenen Lotus wieder auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[30312] = { id = 30312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zweite Chance", description = "Ein törichtes Kontingent hat versucht, durch den östlichen Pass eine Offensive auf die Goldene Treppe einzuleiten, doch sie wurden bombardiert. Die, die es zurückgeschafft haben, befinden sich in einem schlechten Zustand, und noch immer gibt es Verletzte draußen auf dem Feld.\n\nHier sind ein paar Verbände. Bringt die verwundeten Verteidiger mit ihrer Hilfe oder sonstigen Heilungsfähigkeiten, über die Ihr verfügen mögt, wieder auf die Beine.\n\nBitte beeilt Euch, denn es bleibt nicht viel Zeit.", sourceObjective = "Heilt 6 verwundete Verteidiger.", progress = "Es gibt noch mehr Verwundete, um die sich jemand kümmern muss. Bitte helft ihnen, wenn Ihr könnt.", completion = "Die, die Ihr geheilt habt, sind sicher zurückgekehrt. Ich danke Euch, werter Freund. Von ganzem Herzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30313] = { id = 30313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wandernden Nebel", description = "<Er schaut auf die tote Nebelkreatur zu seinen Füßen, dann zu Euch auf und zeigt dann in Richtung des Nebels, der den See umgibt. Offensichtlich möchte er, dass Ihr noch mehr dieser Nebelkreaturen ausfindig macht und tötet.>", sourceObjective = "Tötet 8 Nebelgänger.", completion = "<Er klopft Euch anerkennend auf die Schulter und nickt dankbar.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30314] = { id = 30314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die isolierte Bleichklinge", description = "<Er schaut auf den toten Saurok zu seinen Füßen, dann zu Euch auf und zeigt dann in Richtung des Seeufers. Offensichtlich möchte er, dass Ihr noch mehr dieser Saurok ausfindig macht und tötet.>", sourceObjective = "Tötet 8 Bleichklingen-Saurok.", completion = "<Er lächelt Euch an und nickt dankbar.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30315] = { id = 30315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Normal Quest Test Case" }
quests[30316] = { id = 30316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fernschuss", description = "Eine solch grausame Aufgabe würde ich jemanden mit Euren Fähigkeiten normalerweise nicht zumuten, {class}. Aber da Ihr ohnehin auf dem Schlachtfeld bei der Goldenen Treppe sein werdet, könntet Ihr ein paar abgeschossene Pfeile für unsere Bogenschützen einsammeln?", sourceObjective = "Bergt 12 verschossene Shado-Pan-Pfeile.", sourceObjectiveStatus = "unverified-source-field" }
quests[30317] = { id = 30317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser, Wasser überall", description = "Wie würdet Ihr Euch gern nützlich machen?\n\nEs ist ganz schön trocken gewesen in der letzten Zeit. Ich brauche jemanden, der die Felder im Kernland wässert. Aber hört gut zu: Ihr müsst ALLE Felder wässern.\n\nDie Flugmeisterin Wing Nga dort auf der anderen Seite des Weges bewahrt einige Drachen für mich auf. Schnappt Euch einen davon und werft dann Wasser überall dort ab, wo es trocken und staubig aussieht.", sourceObjective = "Sprecht mit Wing Nga, um Euch einen Drachen zu leihen, und werft Wasser auf 35 staubige Stellen im Kernland ab.", completion = "Hmpf! Ich habe schon auf den ersten Blick erkannt, dass Ihr ein guter Wässerer seid. Ihr habt gute Arme zum Wässern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30318] = { id = 30318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnerjagd", description = "Hallo Ihr da! {name}, stimmt's? Ich habe ein Problem, bei dem mir jemand helfen sollte, dessen Beine besser sind als die meinen.\n\nMein preisgekröntes Huhn ist abgehauen! Jetzt ist es draußen und treibt sich mit anderen Hennen, Wildvögeln und... <schluck> Hähnen mit schlimmen Absichten herum.\n\nMein Hof befindet sich westlich von hier, südlich der Himmelsweite. Könntet Ihr es für mich aufspüren und zurückbringen?", sourceObjective = "Sammelt Hügelprankes Hühner ein, bis Ihr seine Zuchthenne findet.", progress = "Ich schwöre, das hat sie zum ersten Mal gemacht.", completion = "Ihr habt sie gefunden! Ihr habt ein Auge für Federvieh.\n\nIch werde sie fürs Erste festhalten. Keine Sorge, später erhält sie dann ihre Strafe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30319] = { id = 30319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probleme mit Schädlingen", description = "Einer meiner Landarbeiter, Wika-Wika, bewirtschaftet meinen Acker ganz im Westen. Ich weiß, dass er Probleme mit Schädlingen hat.\n\nEr hat zwar viel Schädlingsbekämpfungsmittel, das er auf die Insekten sprühen kann, aber ich fürchte, dass er mit den Murmeltieren nicht zurechtkommt.\n\nKönnt Ihr ihm vielleicht helfen? Bei den ganzen wilden Ho-zen und den Angriffen durch Shed-Ling kann ich es mir nicht erlauben, auch noch wegen herkömmlichen einfachen Schädlingen Ernte zu verlieren.", sourceObjective = "Redet mit Wika-Wika, und stampft dann auf 25 Schwarznasenmurmeltiere.", completion = "Sehr schön. Die Sache wäre erledigt. Gut gemacht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30320] = { id = 30320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenbefreiung", description = "Mir ist einer der Dolche der Geistfetzer der Shao-Tien in die Hände gefallen. Er strahlt eine mächtige Magie aus. Man hat mir gesagt, dass man damit in ihre Geistervortexe eindringen könne.\n\nDie Mogu verwenden sie, um damit Seelen zu besiegen und ihren Willen zu binden. Aber ich hoffe, dass Ihr damit die Seelen auch befreien könnt.\n\nDringt in alle Geistervortexe ein, die Ihr auf der Goldenen Treppe finden könnt, und befreit alle gefangenen Seelen, denen Ihr begegnet.", sourceObjective = "Dringt in die Geistervortexe ein und befreit 15 Pandarenseelen.", progress = "Die Mogu sind in der Lage, Pandarenseelen in tote Objekte zu verpflanzen und sie ihrem Willen zu unterwerfen. Aber die Seelen sehnen sich nach Freiheit. Vielleicht ist dies das Werkzeug, das wir benötigen, um ihnen die Freiheit zu schenken.", completion = "Sehr gut! Ich werde diesen Dolch gut verwahren. Vielleicht erhalten wir wieder einmal die Möglichkeit, ihn zu verwenden.\n\nIch danke Euch vielmals. Ihr seid mit einem gütigen Herzen gesegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30321] = { id = 30321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zweite Unkrautkrieg", description = "Haaaallöchen... Kennt Ihr den Kerl drüb'n auf'm Hof, der... der *hicks*... das Unkrautproblem hat? Gai Lan heißter, glaub' ich. Ich mag den Kerl, echt.\n\nEgaaaal, er meinte, dass wenn ich *hicks* 'nen Abenteurer zum Herausreiß'n von Unkraut schicken könnt', dass er mir Bier schicken würde.\n\nIst wahrscheinlich nich' viel, nur 'n bisschen Unkraut halt.\n\n*hicks*", sourceObjective = "Sprecht mit Gai Lan und vernichtet dann 100 Exemplare Unkraut auf seinem Hof. Das Unkraut könnt Ihr auch vom Rücken eines Reittieres aus jäten.", completion = "Danke, Heeerr *hicks* {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30322] = { id = 30322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geld regiert die Welt", description = "Ich arbeite gerne auf dem Markt, aber etwas daran gefällt mir nicht: das Eintreiben von Schulden.\n\nDie meisten Schulden von Pandaren sind zwar auf Faulheit zurückzuführen, aber es gibt auch ein paar Leute in der Stadt, die einfach nicht zahlen wollen oder zu arm sind.\n\nEinige hier in der Stadt schulden mir Geld. Könntet Ihr mit ihnen reden und sie daran erinnern, was sie mir schulden?", sourceObjective = "Besorgt Gewürzmeister Jin Jaos Bezahlung, Händler Jambeezis Bezahlung, Gastwirtin Lei Lans Bezahlung und Lolo Lios Bezahlung.", progress = "Wisst Ihr, es ist schön, einen Schläg… ähm, ich meine natürlich Helfer... wie Euch zu haben, {class}.", completion = "Ich bin froh, dass diese unangenehme Sache erledigt ist. Es hat Euch doch niemand Ärger bereitet, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[30323] = { id = 30323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tragen das noch nicht einmal", description = "Vor ein paar Wochen hat eine Gruppe dieser wilden Sprungschweif-Shed-Ling meine Schließkassette aufgebrochen und Schmuck entwendet. Seitdem habe ich zwar ein paar Stücke wieder gefunden, sie haben aber immer noch einen Großteil meiner Kollektion.\n\nWenn Ihr zu den Sprungschweifhöhlen geht, bei den Klippen im Norden, solltet Ihr die Augen nach ihnen offen halten. Ich hätte gerne meinen Schmuck zurück.", sourceObjective = "Besorgt einen gestohlenen Reif, einen geplünderten Ring und ein stibitztes Armband.", progress = "Ist es denn zu glauben, wie verantwortungslos und unreif diese Shed-Ling sind? Wissen die nicht, wie viel dieser Schmuck KOSTET?", completion = "Oh, {name}! Ich würde Euch hier auf der Stelle küssen, wärt Ihr nicht... nun, mit Shed-Ling-Staub bedeckt.\n\nIch danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[30324] = { id = 30324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht vor Chi-Chis Haustür", description = "Nicht alle Ho-zen sind gleich. Chi-Chi gehörte zu Wald-Ho-zen... kamen aus Jadewald. Sehr umgänglich.\n\nDie Kunzen-Eindringlinge... sie kommen aus Bergen weit im Norden. Bei Weitem nicht so nett wie Chi-Chi.\n\nSie kommen in unser grünes Land, stehlen alles, lassen großes Durcheinander zurück.\n\nChi-Chi will sie abmurksen. Hilfste mir?", sourceObjective = "Tötet 8 Mitglieder des Kunzen-Stammes in Kunzen.", completion = "Toll! Chi-Chi wusste, dass du das schafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[30325] = { id = 30325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worauf es ankommt", description = "Ich habe diese Kunzen-Ho-zen beobachtet, und mir ist dabei ein Muster aufgefallen. Immer kurz vor einem Angriff führen sie seltsame, barbarische Rituale um ihr Totem herum durch.\n\nWenn wir dieses Ritual stören, halten wir nicht nur künftige Angriffe auf, sondern können ihrer Moral einen Schlag versetzen! Geht also rein, mischt sie ordentlich auf, und sorgt für so viel Chaos wie möglich!", sourceObjective = "Werft 8 Kunzen-Ritualkerzen, tretet viermal auf brennende Glut und tötet 1 Kunzen-Ritualist.", completion = "Hah! Das aufzuräumen wird sie mehrere Tage beschäftigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30326] = { id = 30326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Legenden-Häuptling der Kunzen", description = "Ich habe Leute über die Ho-zen reden gehört, als wären sie einfach nur ein Haufen tumber Idioten... Aber das stimmt nicht! Sie haben auch ein Gehirn - allerdings nutzen sie es nicht so oft.\n\nIch habe erfahren, dass der Kunzen-Stamm zwei Häuptlinge hat - einer ist für Kämpfe zuständig, der andere für Geschichten, Sagen und Erzählungen.\n\nMich würden ihre Geschichten ja wirklich interessieren...", sourceObjective = "Besorgt ein Legendenbuch der Kunzen von einem Kunzen-Legendenhäuptling.", progress = "Ich wette, die Ho-zen-Legenden unterscheiden sich kaum von unseren.", completion = "Oh! Seht Euch das an! Das ist...\n\n<Fischi blättert durch die Seiten und ihr Gesicht verzieht sich.>\n\nÄhm, ich glaube, das ist ein schmutziges Bild. Aber der Rest ist sehr interessant! Ich liebe es, die Denkweise anderer Kreaturen kennen zu lernen. Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30327] = { id = 30327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seil in Flammen", description = "Ich, ähm... nun...\n\nAch, nicht so wichtig. Das war eine dumme Idee.\n\nIch dachte mir nur, dass es ja vielleicht möglich wäre, die Kunzen von einem Angriff abzuhalten, ohne jemanden, nun ja... TÖTEN zu müssen. Mir sind ein paar Seile an der Bergseite aufgefallen. Ich glaube, sie klettern daran zu unseren Höfen hinab und...\n\nNein, vergesst es. Das war ein blöder Gedanke.", sourceObjective = "Verbrennt 6 Kunzen-Seile.", completion = "<Ellas Gesicht erhellt sich.>\n\nIhr habt es getan? Für mich? Oh, habt vielen Dank - danke, danke, danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[30328] = { id = 30328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das tausend Jahre alte Klößchen", description = "Eines meiner beliebtesten Rezepte ist das tausend Jahre alte Klößchen, das mit konserviertem Gemüse gefüllt ist.\n\nIch lasse normalerweise das Gemüse in einem Loch unter meinem Haus gären, aber als ich diesen Morgen danach sehen wollte, war es weg!\n\nDas waren bestimmt diese diebischen Shed-Ling.\n\nBringt mir das Gemüse zurück, und Ihr dürft mir beim Kochen helfen!", sourceObjective = "Besorgt 7 Gefäße konserviertes Gemüse.", progress = "Versucht nicht, eines der Gefäße zu öffnen. Falls Ihr es doch macht, solltet Ihr nicht allzu dicht mit der Nase rangehen.", completion = "Nun, mein Schüler, passt gut auf. Ich zeige Euch jetzt das Geheimnis des tausend Jahre alten Klößchens...", sourceObjectiveStatus = "unverified-source-field" }
quests[30329] = { id = 30329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühmagenpfefferschoten", description = "Einige Pandaren hier mögen unglaublich scharf gewürzte Gerichte. Leider sind meine Möglichkeiten, solche Gewürze zu besorgen, begrenzt.\n\nDie Kunzen-Ho-zen in den Bergen im Westen haben oft Glühmagenpfefferschoten dabei. Ein paar davon würden ein paar Tage reichen.\n\nWürdet Ihr vielleicht einige für mich besorgen? Ihr solltet vielleicht Handschuhe tragen, wenn Ihr sie anfasst.", sourceObjective = "Besorgt 4 Glühmagenpfefferschoten.", progress = "Legt die Schoten einfach nur auf das Schneidebrett hier. Ich will sie lieber nicht selbst anfassen.", completion = "Ich kann nicht verstehen, wie die Ho-zen diese Dinger bei sich tragen können... geschweige denn essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30330] = { id = 30330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trüffelei", description = "Ich mag es, mit Trüffeln zu backen... wenn ich welche finde. Sie wachsen nur oben auf der Himmelsweite, und das in ganz, ganz geringen Mengen.\n\nSie sind eine fantastische Zutat, aber wir dürfen nicht zu viel von ihnen ernten. Aus diesem Grund müssen wir das ersetzen, was wir genommen haben. Holt mir eine Handvoll ausgewachsener Trüffeln und pflanzt dafür einige dieser Sporen.", sourceObjective = "Besorgt 8 Dimmlichttrüffeln und pflanzt 8 Dimmlichttrüffelsporen.", progress = "Wir brauchen nicht viele Trüffeln. Die sind nur für den Geschmack.", completion = "Die werden reichen.\n\nUnd nun, {name}... kommt näher. Ich werde Euch etwas über die Backkunst lehren...", sourceObjectiveStatus = "unverified-source-field" }
quests[30331] = { id = 30331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzenküche", description = "Habt Ihr jemals Mushanschwanzeintopf probiert? Wenn ja, dann war er höchstwahrscheinlich zäh und geschmacklos. Ihr müsst wissen, dass es einen Trick gibt, um den perfekten Mushanschwanzeintopf zuzubereiten: Man muss ihn auf großer Höhe kochen.\n\nIch habe bereits die Zutaten gesammelt. Nehmt diesen Topf mit nach Kunzen oben in den Bergen im Westen und bereitet den Eintopf über ihrem Lagerfeuer zu.", sourceObjective = "Bereitet 20 Schüsseln Mushanschwanzeintopf über dem Lagerfeuer in Kunzen zu.", progress = "Früher ging ich jeden Tag in die Berge, nur um diesen Eintopf zu kochen.\n\nDamals war ich noch jünger.", completion = "Das ist fantastisch! Vom Kochen versteht Ihr wirklich etwas, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30332] = { id = 30332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fettiges Ziegensteak", description = "Wisst Ihr was? Ich glaube, ich werde heute ein Ziegensteak grillen.\n\nNein, nicht von den mickrigen Zottelhörnern aus dieser Gegend. Die haben bei weitem nicht genug Fett auf den Rippen.\n\n<Der Koch tätschelt seinen riesigen Bauch.>\n\nGlaubt Ihr, ich wäre mit mageren Zieglein so stattlich geworden?\n\nNun, die Zottelhörner oben auf der Himmelsweite im Westen... die sind genau richtig.", sourceObjective = "Besorgt 4 fettige Ziegensteaks.", progress = "<Der Koch bereitet konzentriert Gewürze und Soßen für die Steaks vor, die er erwartet.>", completion = "Eine gute Auswahl an Steaks, {name}. Ihr hättet eine Zukunft als Metzger. Wahrscheinlich seid Ihr als {class} jedoch besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[30333] = { id = 30333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das geringere Übel", description = "Wie jede von der Landwirtschaft lebende Gemeinde haben auch wir ab und zu Ärger mit den Shed-Ling.\n\nDie stärksten Sprungschweif-Shed-Ling leben oben in den Klippen im Norden. Sie kommen nur herunter, wenn ihnen das Gemüse ausgeht.\n\nIch hatte, ehrlich gesagt, schon einmal mit Shed-Ling zu tun. Die sind nichts weiter als eine Plage, die unter Kontrolle gehalten werden muss. Und hierfür gibt es nichts effektiveres, als ihre Baumutter zu töten. So einfach ist das.", sourceObjective = "Tötet die Baumutter der Sprungschweife.", completion = "So, das wäre erledigt. Und jetzt konzentrieren wir uns zur Abwechslung mal wieder auf die Landwirtschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30334] = { id = 30334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stehlen ist böse… Zurückstehlen ist in Ordnung", description = "Die Ho-zen aus den Bergen im Westen stehlen immer noch Gemüse von den anderen Bauern. Da ich so nahe bei Halbhügel lebe, bleibe ich von Angriffen der Ho-zen meistens verschont, aber meine Freunde haben nicht so viel Glück.\n\nMeiner Meinung nach stehlen die viel mehr, als sie überhaupt essen können. Wenn Ihr unversehrtes Gemüse in diesen Bergen findet... stehlt es zurück!", sourceObjective = "Stehlt 16 Exemplare gestohlenes Gemüse zurück.", progress = "Habt Ihr es?", completion = "Danke! Ich werde dafür sorgen, dass es an die anderen Bauern verteilt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[30335] = { id = 30335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plünderung Einhalt gebieten", description = "Die Kunzen-Ho-zen oben in den Bergen im Westen spielen verrückt, zünden ihre Feuer an und singen lautstark. Meinen Erfahrungen nach bedeutet das, dass eine Plünderungsaktion bevorsteht.\n\nWir können zwar nicht viel tun, um sie aufzuhalten, aber wir können zumindest einige von ihnen dezimieren, bevor sie angreifen.", sourceObjective = "Tötet 12 Kunzen-Ho-zen.", progress = "Der Angriff kann jeden Moment beginnen. Wir müssen vorbereitet sein.", completion = "Sie werden zwar angreifen, aber mein Hof - und die Höfe meiner Freunde - sollten nicht gefährdet sein.\n\nJedenfalls nicht, wenn wir es verhindern können. Stimmt's, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[30336] = { id = 30336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kunzen-Jägerhäuptling", description = "Soviel ich weiß, haben die Kunzen-Ho-zen zwei Häuptlinge. Einer ist harmlos - er kümmert sich um Tränke, Medizin und Sagen. Der andere ist für die Kunzen-Jäger zuständig - und das Einzige, was die in letzter Zeit gejagt haben, ist unsere Ernte.\n\nDer Jägerhäuptling ist ein Problem, das wir angehen müssen. Die Bauern hier wären Euch dankbar, wenn Ihr Euch um ihn \"kümmern\" könntet.", sourceObjective = "Tötet den Kunzen-Jägerhäuptling.", completion = "Die Ho-zen werden heute Nacht bestimmt ein großes Ritual abhalten, um einen neuen Jägerhäuptling zu küren.\n\nIch bin einfach nur froh, dass wir Bauern uns in der Zwischenzeit erholen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30337] = { id = 30337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affenartige Sabotage", description = "Die Ho-zen bestehlen uns, und wir stehlen unsere Sachen wieder zurück. Das muss irgendwann einmal aufhören.\n\n<Bauer Yoon gibt Euch ein Fass mit Feuerwerkskörpern.>\n\nFindet einen Teil unserer gestohlenen Vorräte in ihrem Berglager im Westen, und legt diese Feuerwerkkörper daneben. Wenn die Explosionen losgehen, denken sie hoffentlich, dass unsere Vorräte gefährlich sind, und hören mit dem Stehlen ganz auf.\n\nEinen Versuch ist es doch wert, oder?", sourceObjective = "Verwendet das Fass mit Feuerwerkskörpern neben dem Stapel gestohlener Waffen, dem Stapel gestohlener Werkzeuge, dem Vorrat gestohlenen Biers und dem Haufen gestohlenen Getreides.", completion = "Hoffentlich hören sie jetzt mit dem Stehlen unserer Vorräte auf. Ich jedenfalls würde kein explosives Bier trinken wollen - oder mit einer Harke arbeiten, die gleich in die Luft fliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30338] = { id = 30338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schwer wiegende Aufgabe", description = "Mir will beim besten Willen nicht einfallen, warum nur die Mogu all ihre Statuen und ihren anderen Tand da unten im See platziert haben sollten. Ich wette dort unten war nicht immer Wasser, aber im Falle von Regen scheint es mir dennoch ein äußerst unkomfortabler Ort zu sein.\n\nAber wer versteht schon die absonderlichen Absichten der Mogu...?\n\nWürde es Euch etwas ausmachen, dort runter zu tauchen und alles hochzuholen, was auch nur annähernd tragbar ist? Ich wäre Euch wirklich sehr dankbar dafür.", sourceObjective = "Bergt 8 Moguartefakte.", progress = "Habt Ihr ein oder zwei hübsche Artefakte für mich gefunden? Wenn es Euch gelingt, werde ich mich bei Euch mit einer fulminanten Umarmung bedanken!", completion = "Ihr erstaunt mich immer wieder! Ihr könnt nicht nur in dieser hübschen und wohl recht schweren Rüstung schwimmen, sondern auch noch ein halbes Dutzend güldener Waffen mit Euch herumschleppen! Von all Euren Fähigkeiten ist dies doch wohl die erstaunlichste, nicht wahr?\n\nIch danke Euch, Beherrscher der Binnengewässer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30339] = { id = 30339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich die Hände schmutzig machen", description = "Dieser See hier zählt zu den besten Fischgewässern in ganz Pandaria. Ich habe mir genug Bräu für den ganzen Tag mitgenommen, aber leider vergessen, Köder einzupacken.\n\nWer kann auch schon an alles denken?\n\nWenn Ihr mir ein paar Köder entlang der Küstenlinie einsammelt, werde ich an Euch denken, wenn ich meine Beute verkaufe. Oh, und das Bezahlen werde ich natürlich nicht vergessen. \n\nAlso, habt Ihr Interesse?", sourceObjective = "Sammelt 12 frische Weißblütenwürmer.", progress = "Einen ganzen Tag nur angeln! Und dazwischen einfach nichts tun!", completion = "Ihr macht Eurem Volk Ehre, indem Ihr mir einfachem Händler helft. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30340] = { id = 30340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischen Tür und Angel", description = "Ich wollte hier einen wundervollen Angeltag verbringen, aber ich habe meine Angelrute vergessen. Beim Angeln muss man ja an so vieles denken... Das kann sich ja niemand merken.\n\nDiese Schilfhalme am Ufer würden gute Angelruten abgeben. Wenn Ihr mir ein paar davon einsammelt, werde ich an Euch denken, wenn ich meine Beute verkaufe. Oh, und bezahlen werde ich Euch natürlich auch. \n\nAlso, habt Ihr Interesse?", sourceObjective = "Sammelt 12 Weißblütenschilf.", progress = "Einen ganzen Tag nur angeln! Und dazwischen einfach nichts tun!", completion = "Ihr macht Eurem Volk Ehre, indem Ihr mir einfachem Händler helft. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30341] = { id = 30341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Beobachtung", description = "<Er schaut auf den toten Mogu zu seinen Füßen, dann zu Euch auf und zeigt dann in Richtung des Seeufers. Offensichtlich möchte er, dass Ihr noch mehr dieser Moguspäher ausfindig macht und tötet.>", sourceObjective = "Tötet 8 Shao-Tien-Vermesser.", progress = "<Er starrt Euch ausdruckslos an.>", completion = "<Er verbeugt sich dankbar vor Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30342] = { id = 30342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gierige Zähne, zarte Füßchen", description = "Als ich mich wieder einmal meinem vergnüglichen Wassertreten gewidmet habe, ist einer dieser widerwärtigen Krokilisken aus dem Wasser aufgetaucht und hat versucht, mir in den Fuß zu beißen! Unverschämtheit! Ich habe mich entschieden, meine müden Füße fürs Erste vom Wasser fernzuhalten. Aber ich vermisse meine Leibesübungen im Wasser jetzt schon.\n\nWäret Ihr vielleicht so freundlich, einen oder sechs Krokilisken für mich zu töten? Und gewährt ihnen keine Gnade. Wer mich so fürchterlich erschrickt, verdient sie nämlich nicht.", sourceObjective = "Tötet 6 Stillwasserkrokilisken.", completion = "Habt ihr gehört, meine lieben und wunderschönen Füße? Die Zeit des Leidens ist vorbei! Ich kann Euch wieder in das herrliche Nass eintauchen!\n\nOh, Ihr seid aber auch zu liebenswürdig! Vielleicht wollt Ihr mir ja eines Tages beim Wassertreten Gesellschaft leisten. Wir könnten dann über die alten Zeiten plaudern, als Ihr großzügigerweise diese Krokodile abgeschlachtet habt, um meine verängstigten und unschuldigen Füße zu schützen. Was war das doch nur für ein großartiger Tag...", sourceObjectiveStatus = "unverified-source-field" }
quests[30343] = { id = 30343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfackeln!", description = "Ich bin Himmelshäscher Sturmgeheul, Kapitän des Luftschiffes Garroshs Faust und Kommandant dieser Operation.\n\nEure erste Aufgabe besteht darin, die 7. Flotte abzufackeln, während sie noch vor Anker liegt.\n\nKapitän Droks Marinesoldaten halten während der Operation Eures Teams die Stellung am Hafeneingang.\n\nPlatziert Pulverfässer in den Frachträumen aller Schiffe und formiert Euch dann am Hafeneingang neu, um Sprengmeister Zündlunte Bescheid zu geben. Er wird den Sprengstoff zünden und dem Luftschiff das Signal für den Weiterflug geben.", sourceObjective = "Platziert Pulverfässer in den Frachträumen aller sechs Schiffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30344] = { id = 30344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Dynastie", description = "Ich frage mich, ob ich Euch mit noch einer Aufgabe belästigen könnte. Meine Tochter, die gute Kommandantin der Schildwachen Lyalia hier, verbietet mir, ins Feld zu ziehen.\n\nJeden Tag, den ich in dieser Oubliette gefangen war, war ich gezwungen, auf die Ruinen im Norden zu starren. Es reizt mich, sie zu erkunden.\n\nWenn wir dort sind, wo ich vermute, dass wir sind, könnten diese Ruinen der Schlüssel sein, den wir benötigen, um die sagenhaften Teiche der Jugend zu finden!\n\nBitte, {class}! Geht zu diesen Ruinen und bergt alle Tafeln, die noch Schrift aufweisen.", sourceObjective = "Besorgt 6 dynastische Tafeln.", progress = "Es ist eine Sache, die Verlorenen Dynastien zu erforschen. Es ist zweifellos etwas anderes, deren alte Ruinen zu besuchen.\n\nMir wird dabei schwindelig wie seit Jahrhunderten nicht mehr!", completion = "Oh! Fabelhaft! Fabelhaft!\n\nDer eine Ausflug von Euch hat meine Forschung weiter vorangebracht als zehn Jahre des Lesens in staubigen Folianten und zerfallenden Schriftrollen...\n\nUnd diese \"Mogu\", die Ihr gesehen habt. Ich habe auch in dieser Richtung geforscht und mit Kang darüber geredet.\n\nIch vermute jetzt, dass es sich bei ihnen um das Volk der Verlorenen Dynastien handelt, die mein Forschungsgebiet sind.\n\nNatürlich bedeutet das gleichzeitig, dass sie diejenigen sind, die einst die Teiche der Jugend kontrolliert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30346] = { id = 30346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind die Teiche?", description = "Vielleicht wissen diese Mogu, wo die Teiche sich befinden.\n\nUnsere Späher haben berichtet, einen Kommandanten an der Südseite der Ruinen von Dojan gesichtet zu haben.\n\nTötet ihn und bringt jegliche Information mit, die er bei sich trägt. Sie sollten Euch zum Teich führen.", sourceObjective = "Besorgt die Dojani-Befehle.", progress = "<Ihr spürt die Anwesenheit von Wissenshüter Vaeldrin, dann hört Ihr seine Stimme in Eurem Verstand.>\n\nHmm. Ich bin immer noch nicht sicher, was die Verweise auf \"Tortur\" in Bezug auf die Teiche der Jugend bedeuten sollen.", completion = "Gut gemacht, {name}. Hmm, es sieht so aus, als ob die Mogu hier wären, um alte Relikte und Waffen aus ihrer vergessenen Dynastie zu sammeln. Das ist allerdings ein Problem, dessen wir uns später annehmen können.\n\nAh! Hier ist ein Verweis auf die Teiche der Jugend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30347] = { id = 30347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teiche der Jugend", description = "Norden! Geht nach Norden zu den Teichen der Jugend. Holt etwas von dem Wasser, aber seid wachsam.\n\nDie Mogu betrachten sie als \"hochrangiges\" Ziel. Kang Dornstab wird sich dort mit Euch treffen, falls er Euch nicht schon erreicht hat.", sourceObjective = "Besorgt ein wenig des Wassers der Jugend.", progress = "Nichts gibt einem mehr Sinn für Dringlichkeit, als sterblich zu sein.", completion = "Ihr... Ihr habt die Teiche gefunden! Die Wasser existieren!\n\nAber etwas ist nicht richtig. Ich fühle gleiche Anteile Schatten und Licht in dieser Phiole wirbeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[30348] = { id = 30348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsterblichkeit?", description = "Etwas ist... nicht richtig. Das Wasser fühlt sich seltsam an.\n\nAls wir hier angekommen sind, habe ich die Präsenz des Lichts gefühlt, stark und pulsierend, weit im Norden.\n\nAber dieses... dieses Wasser ist irgendwie mit einem Makel behaftet. Befleckt durch Mogumagie.\n\nIch glaube, es ist am besten, wenn ich nur einen Schluck probiere, dann sehen wir, was passiert.", sourceObjective = "Beobachtet Vaeldrin, während er das Wasser der Jugend probiert.", completion = "Wa... was ist passiert? Das Wasser... es... es überträgt Leben nur. Es schafft kein neues Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30349] = { id = 30349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung aus Dojan", description = "Während Ihr bei den Ruinen wart und für meinen Vater Tafeln abgestaubt habt, habe ich fünf Späher an umherziehende Mogupatrouillen verloren.\n\nDiese Kreaturen haben offensichtlich nur geringes Interesse an Frieden und sind ungefähr ebenso vertrauenswürdig wie die Horde.\n\nSie sind jedoch zu zahlreich und wir zu schwach.\n\nGeht zu den Ruinen westlich von hier und dünnt die Reihen der Mogu aus. Jemanden wie Euch werden sie nicht erwarten, {class}.", sourceObjective = "Tötet 6 Dojanieroberer, 8 Dojanispäher und 4 Dojanivollstrecker.", completion = "Gut gemacht, {name}. Noch ein paar solcher Missionen und wir müssen Euch vielleicht zu einer Ehrenschildwache machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30350] = { id = 30350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ekliger Gaumenschmaus", sourceObjective = "Sammelt 5 unversehrte Huscherdrüsen.", progress = "Mama Dornstab hat immer gesagt, Ekliger Gaumenschmaus heilt jeden Hunger, auf die eine oder andere Weise.", completion = "Ha! Damit kann ich Eintopf machen, der so stark ist, dass er diese spindeldürren Elfen ruck, zuck auf die Beine bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30351] = { id = 30351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lotustee", description = "Die Mogu lieben ihre Gifte und Flüche. Mama Dornstab hat immer gesagt, dass Lotustee sämtliche Moguflüche heilen würde.\n\nIch habe ein paar kaiserliche Lotuspflanzen in der Nähe der Ruinen von Dojan gesehen. Wir sollten hingehen und ein paar der Blätter pflücken und griffbereit halten, für den Fall, dass die Mogu unruhig werden.\n\nIch bekomme dann zudem die Chance, meine Fäuste ein paar Mogufratzen vorzustellen.", sourceObjective = "Sammelt 20 Kaiserliche Lotusblätter.", progress = "Ich habe noch nie so viele Mogu gesehen. Sie waren immer schon ein Ärgernis, aber noch nie so schlimm.", completion = "So geht das! Ihr pflückt, ich prügle!", sourceObjectiveStatus = "unverified-source-field" }
quests[30352] = { id = 30352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kranich-Meisterschaft", description = "Die Sache bei der Jagd auf Vögel ist die, dass man Munition braucht - und ich habe keine. Die Sache bei der Jagd mit Nesingwary ist, dass man beweisen muss, dass man in Abschüssen und Prahlerei nicht nachlässt.\n\nKeine Jagd, keine Prahlerei. Und ich mag Prahlerei, also ist dies eine schlechte Situation.\n\nKann ich Euch anheuern, ein paar Karpfenjäger für mich zu töten? Ihr findet sie rauf und runter am Fluss westlich von hier. Es sind ziemlich viele, also jagt nebenher ruhig ein wenig.", sourceObjective = "Tötet 12 Karpfenjäger.", completion = "Fantastisch. Das Einzige, was diesen Jagdausflug noch unterhaltsamer machen würde, wäre ein Stuhl. Hier ist die Belohnung, die ich Euch versprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30353] = { id = 30353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterlicher Profit", description = "Ein Wort: Tigerblut!\n\nDas wird sich besser verkaufen als damals Saronit auf dem Schwarzmarkt. Besonders, nachdem ich ein Gerücht über die tolle stärkende Wirkung und so verbreitet habe.\n\nUnd im Dschungel wimmelt es nur so von Tigern. Könnt Ihr ein paar mit Tigerblut gefüllte Phiolen für mich auftreiben? Ich werde Euch auch an der Gaunerei beteiligen.", sourceObjective = "Besorgt 12 mit Tigerblut gefüllte Phiolen.", progress = "Ich mag es, mit Nesingwary zu jagen und so, aber ihm geht es dabei ums Jagen. Mir geht es um den Profit, und er bezahlt uns nicht.", completion = "Großartig! Dieses Zeug wird mir drüben in Kalimdor eine Menge Geld verschaffen. Hier ist Euer Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[30354] = { id = 30354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Schwester bleibt zurück", sourceObjective = "Rettet 8 Gefangene der Mogu.", completion = "Es gibt nur wenige von uns, und es ist eine große Erleichterung, solche Hilfe zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30355] = { id = 30355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneute Zurückeroberung", sourceObjective = "Beschafft 10 Moguartefakte.", progress = "Jedes Artefakt in unserem Besitz ist eine Waffe weniger in den Händen der Mogu.", completion = "Gut gemacht, {name}. Ihr habt dem Kind das Schwert aus der Hand genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30356] = { id = 30356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterbrechung ihrer Nachschublinie", description = "Die Mogueroberer verwenden Portale als Verbindung zum Kun-Lai-Gipfel. Sie schaffen Verstärkung und Vorräte dorthin.\n\nDarüber hinaus schicken sie ihre Gefangenen durch diese Portale.\n\nGeht zu den Ruinen von Korja und vernichtet so viele dieser Korjanieroberer, wie Ihr finden könnt.", sourceObjective = "Tötet 8 Korjanieroberer.", completion = "Ihr habt uns wertvollen Raum zum Atmen verschafft, sodass wir unsere Wunden lecken und einen Gegenangriff vorbereiten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30357] = { id = 30357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinpflug-Konvoi", sourceObjective = "Setzt kaiserliche Lotusumschläge bei 7 Gesandten von Steinpflug ein.", completion = "Es ist lange her, seit ich meine Ärmel hochgekrempelt und den Bedürftigen geholfen habe. In meiner Begierde nach Unsterblichkeit hatte ich vergessen, warum ich Priester geworden bin.\n\nDanke, dass Ihr mich daran erinnert habt, dass es Gutes in dieser Welt gibt, für das es sich zu kämpfen lohnt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30359] = { id = 30359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Oberste Eroberer", sourceObjective = "Sucht Lyalia und tötet Bodenbrecher Brojai.", completion = "Danke, dass Ihr meine Tochter gerächt habt. Ich bin allerdings nicht bereit, ihren Tod hinzunehmen.\n\nIch habe immer noch die Wasser der Jugend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30360] = { id = 30360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung an Steinpflug", description = "Mein Vater gab sein Leben für mich. Tyrande gab mir ihr Vertrauen. Meine Schildwachen gaben mir ihre Treue.\n\nEs ist Zeit, dass ich es ihnen vergelte.\n\nWo Brojai nun tot ist, können wir die restlichen Mogu erledigen. Die nächste Bedrohung sind die Mantis.\n\nGeht nach Norden nach Steinpflug und unterstützt sie dort. Sagt ihnen, ich komme mit so vielen Schildwachen, wie ich ausheben kann, und helfe ihnen bei der Verteidigung ihrer Stadt gegen die Mantis.", sourceObjective = "Reist nach Steinpflug im Tal der Vier Winde.", completion = "Mantis aus dem Süden? Das ist kein guter Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[30361] = { id = 30361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mantis", description = "Die Mantis! Sie kamen aus dem Nichts, schlugen unseren Konvoi in Trümmer und versprengten unsere Leute in alle Richtungen.\n\nJetzt bereiten sie einen Angriff auf Steinpflug vor.\n\nBitte, {class}, vernichtet ein paar dieser Bestien, bevor sie zahlreich genug sind, um uns zu umzingeln.\n\nWenn mein Cousin, Botschafter Len, immer noch am Leben ist und sich in unserem Konvoi befindet, sollte er Euch für Eure Hilfe belohnen können.", sourceObjective = "Tötet 10 Mantis der Ik'thik.", completion = "Danke für Eure Hilfe, {class}! Ich habe noch nie gesehen, wie sich jemand so den Mantis entgegengeworfen hat.\n\nNun, außer den Shado-Pan natürlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[30363] = { id = 30363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Offensive gehen", description = "Ha! Also hat mein Vater zwanzig Jahre unserer Leben einer vergeblichen Mühe wegen verschwendet!\n\nIch übernehme das Kommando.\n\nAls Tyrande uns hierhergeschickt hat, machte sie sehr deutlich, dass wir nicht zurückkommen sollen, bis wir das Licht gefunden haben, das sie in ihren Visionen gesehen hatte. Es ist jetzt offensichtlich, dass es sich dabei nicht um die Teiche der Jugend gehandelt hat.\n\nIch möchte Euch bitten, nach meinem Späher zu suchen. Ich habe sie ausgesandt, den Kranichtempel zu erkunden, aber sie ist nicht zurückgekehrt.\n\nBesorgt ihren Bericht und trefft Euch mit uns beim Lager der Schildwachen weiter im Westen.", sourceObjective = "Besorgt den Bericht der Schildwache des Übergriffs.", progress = "Habt Ihr den Späher gefunden?", completion = "{name}, wie immer zur rechten Zeit. Es hat sich herausgestellt, dass auch die Mogu wissen, wie man Portale verwendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30376] = { id = 30376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung stirbt zuletzt", sourceObjective = "Sprecht mit Lun Mai in Steinpflug.", completion = "Endlich ein paar gute Nachrichten. Ich werde sofort einen Falken nach Winterblüte ausschicken und sie wissen lassen, dass der Tempel des Roten Kranichs sicher ist.\n\nMit dem Ausbruch des Sha und der zunehmenden Aggression der Mantis steht es um unsere Truppenstärke momentan nicht zum Besten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30379] = { id = 30379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Gina", progress = "Jetzt steht doch nicht einfach so rum und haltet Maulaffen feil. Was gibt es denn?!", completion = "Oh, was für ein makelloser Edelstein!\n\nWenn Ihr mir weiterhin solche Geschenke macht, kann ich mich vielleicht bald zur Ruhe setzen!" }
quests[30380] = { id = 30380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Gina", progress = "Heute ist viel los auf dem Markt. Was kann ich für Euch tun?", completion = "Oh, was für ein hübscher Apfel! Diese süßen Früchte mag hier wirklich jeder." }
quests[30381] = { id = 30381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Ella", progress = "Habt Ihr selbst Haustiere? Ich mag Katzen, aber Hunde habe ich auch gern.", completion = "Oh, eine Jadekatze!\n\nMein Vater und ich haben immer in den Feldern nach ihnen gesucht. Er hat gesagt, sie würden Glück bringen." }
quests[30382] = { id = 30382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Ella", progress = "Heute ist ein wirklich schöner Tag, findet Ihr nicht?", completion = "Oh, ich danke Euch. Diese Feder ist ja wirklich wunderschön." }
quests[30383] = { id = 30383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Ella", progress = "Was? Oh, hallo. Wie geht es Euch denn?", completion = "Oh, die sind wirklich selten. Ich danke Euch vielmals dafür." }
quests[30384] = { id = 30384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blendet sie!", description = "Sonnenläufer der Horde! Kurz bevor Ihr angekommen seid, haben wir einen ihrer Späher bei der Oubliette patrouillieren sehen.\n\nIch weiß nicht, wie er dorthin gekommen ist, aber ich kann Euch versichern, dass er garantiert nicht alleine ist. Das sind sie nie.\n\nTötet den Späher der Sonnenläufer, bevor er über unsere Position Bericht erstatten kann.", sourceObjective = "Tötet den Späher der Sonnenläufer.", completion = "Sonnenläufern kann man nicht trauen. Es handelt sich bei ihnen um den kriegerischsten Zweig der taurischen Armeen der Horde.\n\nDanke für Eure Hilfe, {name}. Bitte nehmt dies als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30385] = { id = 30385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Für Eure Hilfe danke ich Euch von ganzem Herzen. Anji wartet in der Garnison der Untergehenden Sonne im Westen auf Euch.\n\nMöge Euch ein guter Tag beschieden sein.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", completion = "Willkommen. Hat Chen Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[30386] = { id = 30386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Ella", progress = "Seid gegrüßt an diesem schönen Tag.", completion = "Oh, Garnelenklößchen? Mein Lieblingsessen!\n\nDankeschön." }
quests[30387] = { id = 30387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Gina", progress = "Besser viele Kunden als gar keinen. Und wie kann ich Euch helfen?", completion = "Was für eine interessante kleine Figur. Wirklich hübsch. Ich danke Euch vielmals." }
quests[30388] = { id = 30388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Gina", progress = "Was habt Ihr denn da Schönes?", completion = "So eine hübsche Feder würde einen guten Preis erzielen. Aber die verkaufe ich nicht. Danke für das schöne Geschenk." }
quests[30389] = { id = 30389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Gina", progress = "Hallo, {name}. Lernt Ihr so langsam die Leute in der Stadt kennen?", completion = "Oh, wie schön! Ihr habt mir eine Sumpflilie gebracht.\n\nWoher wusstet Ihr, dass es meine Lieblingsblumen sind?" }
quests[30390] = { id = 30390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Gina", progress = "Ich bin schon den ganzen Tag schwer beschäftigt. Hier ist manchmal ziemlich viel los.", completion = "Ihr bringt mir an diesem turbulenten Markttag etwas zu essen? Das ist aber lieb von Euch!" }
quests[30391] = { id = 30391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für den alten Hügelpranke", progress = "Ich hab' schon genug Probleme mit meinem Hof. Eure kann ich nicht auch noch gebrauchen.", completion = "Oh, für mich? Das ist aber wirklich nett von Euch." }
quests[30392] = { id = 30392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für den alten Hügelpranke", progress = "Die verfluchten Affen waren wieder auf meinem Hof. So was kann einem wirklich die Laune verhageln.", completion = "Na, das is' ja echt nett. Hmpf." }
quests[30393] = { id = 30393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für den alten Hügelpranke", progress = "Was darf's heute sein, {race}?", completion = "Hmpf, das is' aber 'n feiner Zug von Euch, dass Ihr so an mich denkt.\n\nDanke." }
quests[30394] = { id = 30394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für den alten Hügelpranke", progress = "Kann ein alter Mann denn hier keine Ruhe finden?", completion = "...\n\nMein Sohn, Tai… als kleiner Junge hat er die gesammelt.\n\nAls seine Mutter starb, sagte ich ihm, sie seien Nachrichten von ihr, die vom Himmel fallen.\n\n<Der alte Hügelpranke verfällt in düsteres Schweigen.>" }
quests[30395] = { id = 30395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für den alten Hügelpranke", progress = "Es steht 'ne Ernte bevor, und mein Rücken macht mir wieder Ärger. Was soll's, wir alle müssen hier irgendwie zurechtkommen.", completion = "Oh, diese Blumen sind ziemlich selten.\n\nWusstet Ihr, dass die Glück bringen sollen? Vielleicht fällt meine Ernte ja doch noch gut aus. Danke." }
quests[30396] = { id = 30396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für den alten Hügelpranke", progress = "Meine Frau machte früher die leckerste geschmorte Schildkröte überhaupt! Wie ich sie vermisse.", completion = "Dieses Gericht habe ich seit dem Tod meiner Frau nicht mehr gegessen. Auf irgendeine Weise scheint sie Euch zu mir geschickt zu haben.\n\nDanke, {race}." }
quests[30397] = { id = 30397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Chi-Chi", progress = "Was gibt's?", completion = "Schöner Stein! Ihr dumm, wenn Ihr den hergebt. Egal, jetzt gehört er mir!\n\nDanke, {race}!" }
quests[30398] = { id = 30398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Chi-Chi", progress = "Ich bin kein Bergaffe - glaubt das ja nicht.", completion = "Für mich? Roter Apfel? So glänzend! So saftig! Danke!" }
quests[30399] = { id = 30399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Chi-Chi", progress = "Chi-Chi war erster Ho-zen-Bauer. Wenn ich das geschafft hab', dann Ihr auch.", completion = "Ooh, sehr alt, sehr wertvoll. Ich mag Kätzchen. Habe eins von Mädchen Ella." }
quests[30400] = { id = 30400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Chi-Chi", progress = "Verfiddelte Berg-Ho-zen! Wissen nicht, wie hart der kleine Chi-Chi arbeitet. Böse Affen!", completion = "Du meine Güte. Wisst Ihr, was das ist? Eine Frikfrak! Nur etwas für Anführer!\n\nDas heißt also… Ihr glaubt, ich bin Anführer? Jetzt sind wir Anführerfreunde, {name}." }
quests[30401] = { id = 30401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Chi-Chi", progress = "Kleiner Chi-Chi hat sein ganzes Leben hier verbracht. Das ist mein Zuhause.", completion = "Oh! Schönes Blümchen! Darf ich behalten, ja? Danke! Wiedersehen!" }
quests[30402] = { id = 30402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Chi-Chi", progress = "Chi-Chi arbeitet den ganzen Tag auf dem Feld. So müde!", completion = "Oh, ein Pfannengericht nach Vier-Winde-Art. Danke!" }
quests[30403] = { id = 30403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Sho", progress = "Ja, {class}. Was kann ich für Euch tun?", completion = "Für mich? Oh, danke sehr!" }
quests[30404] = { id = 30404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Sho", progress = "Pssst! Hört. Man muss stets wachsam sein.", completion = "Danke." }
quests[30405] = { id = 30405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Sho", progress = "Der erste Schritte zur Disziplinierung Eures Geistes ist die Disziplinierung Eures Körpers.", completion = "Ich weiß die Geste zu schätzen, {race}." }
quests[30406] = { id = 30406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Sho", progress = "Die Wache endet nie.", completion = "Ich weiß die Geste zu schätzen, {race}. Danke, dass Ihr an mich gedacht habt." }
quests[30407] = { id = 30407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Sho", progress = "Ich habe hart daran gearbeit, die Ho-zen oben auf dem Berg auszurotten.", completion = "Ich war nie jemand, der sich mit hübschem, nutzlosem Tand umgibt, aber ich weiß, dass Ihr mir das als Zeichen der Freundschaft schenkt. Dafür danke ich Euch. Wenn ich diese Blume ansehe, werde ich an Euch denken." }
quests[30408] = { id = 30408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Sho", progress = "Schwankt nie in Eurer Stärke.", completion = "Ah, das ist das beste Geschenk, dass mir geben konntet! Ein Krieger braucht Stärke!" }
quests[30409] = { id = 30409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Haohan", progress = "Wart Ihr schon beim Haus des Bundes der Ackerbauern in Halbhügel?", completion = "Oh ja, dieser Rubin wird sich sehr gut mit dem Rest meiner Sammlung machen." }
quests[30410] = { id = 30410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Haohan", progress = "Wie geht's voran auf dem Hof?", completion = "Hmm, ich mag einen hübschen Apfel wirklich." }
quests[30411] = { id = 30411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Haohan", progress = "Was gibt's? Ich bin ein vielbeschäftigter Mann.", completion = "Oh, das ist wirklich exquisite Handarbeit. Wo habt Ihr das bloß her?" }
quests[30412] = { id = 30412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Haohan", progress = "Hallo {race}.", completion = "Hmm, das ist eine wirklich schön glänzende Feder. Ich werde sie zu meiner Sammlung seltener Gegenstände legen." }
quests[30413] = { id = 30413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Haohan", progress = "Ein guter Bauer hält seine Erde gepflügt, damit sie bepflanzt werden kann. Ungepflügter Boden nützt niemandem was, stimmt's, {name}?", completion = "Hmm, ich schätze, diese Blumen sollen Glück bringen. Ich fühle mich geehrt, dass Ihr sie mir gebt." }
quests[30414] = { id = 30414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Haohan", progress = "Ein guter Bauer weiß, wann es Zeit ist zu arbeiten und wann es Zeit ist, zu essen! Man muss sich auch an den Früchten seiner Arbeit erfreuen können, stimmt's?", completion = "Gegrilltes Tigersteak! Für mich? Woher wusstet Ihr, dass das mein Leibgericht ist?" }
quests[30416] = { id = 30416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Bauer Fung", progress = "Hey, es ist die Stadtpfote!", completion = "Oh, das ist ein sehr schöner Stein." }
quests[30417] = { id = 30417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Bauer Fung", progress = "Wie geht es Euch, {race}?", completion = "So ein schöner Apfel für mich?" }
quests[30418] = { id = 30418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Bauer Fung", progress = "Was kann ich für Euch tun?", completion = "Hmmm, eine interessante kleine Statue." }
quests[30419] = { id = 30419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Bauer Fung", progress = "Hallo {race}!", completion = "Das ist eine sehr seltene blaue Feder. Danke." }
quests[30420] = { id = 30420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Bauer Fung", progress = "Nichts fühlt sich besser an als das Gefühl, wenn die Aussaat erledigt ist.", completion = "Oh, eine wirklich seltene Blume." }
quests[30421] = { id = 30421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Bauer Fung", progress = "Ich glaube, mein Magen knurrt.", completion = "Woher wusstet Ihr, dass das mein Leibgericht ist? Danke." }
quests[30422] = { id = 30422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Fischi", progress = "Ich habe den ganzen Tag Yaks zusammengetrieben.", completion = "Ooh, ich habe noch nie einen solch hübschen roten Stein gesehen. Danke, {name}!" }
quests[30423] = { id = 30423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Fischi", progress = "Ich habe den ganzen Tag Shed-Ling gejagt.", completion = "Mein Magen knurrt schon den ganzen Morgen! Das ist das perfekte Geschenk." }
quests[30424] = { id = 30424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Fischi", progress = "Ich habe den ganzen Vormittag mit Schweinen gerungen.", completion = "Oh, eine hübsche Jadekatze! Das macht mich wirklich glücklich, {name}!" }
quests[30425] = { id = 30425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Fischi", progress = "Ich habe den ganzen Tag Würmer ausgegraben.", completion = "Whoa, so eine hübsche Farbe habe ich ja noch nie gesehen. Danke, {name}!" }
quests[30426] = { id = 30426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Fischi", progress = "Ich bin den ganzen Tag mit den Fischen geschwommen.", completion = "Mein Opa hat immer gesagt, dass diese Blummen viel Glück bringen. Danke, {name}!" }
quests[30427] = { id = 30427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Fischi", progress = "Ich bin den ganzen Tag auf Bäume geklettert.", completion = "Junge, Junge, das mag ich am liebsten! Danke, {name}!" }
quests[30428] = { id = 30428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Tina", progress = "Wie geht es Euch heute, {race}?", completion = "Ohhh, ein glitzernder, glänzender Edelstein! Ich liebe ihn!" }
quests[30429] = { id = 30429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Tina", progress = "Wie sehe ich heute aus, {name}?", completion = "Oh, meine Güte, danke, {name}." }
quests[30430] = { id = 30430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Tina", progress = "Wisst Ihr, es ist schwer, immer so gut auszusehen.", completion = "Meine Güte, das ist wunderschön! Vielen Dank, {name}." }
quests[30431] = { id = 30431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Tina", progress = "Möchtet Ihr Euch vielleicht ein wenig zu mir setzen, {race}?", completion = "Oh, diese blaue Feder wird meine blauen Augen zum Strahlen bringen. Danke, {name}." }
quests[30432] = { id = 30432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Tina", progress = "Wie geht es auf dem Hof voran?", completion = "Oh, das wird mir viel Glück bringen! Danke, {name}." }
quests[30433] = { id = 30433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Tina", progress = "Bitte grüßt Bauer Yoon von mir.", completion = "Oh, meine Leibgericht! Lecker!" }
quests[30434] = { id = 30434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Jogu", progress = "Habt Ihr vielleicht ein Kupferstückchen für ein kleines Getränk?", completion = "Oh, ein hübscher Stein! Ich werde ihn ansehen, während ich einen Schluck trinke." }
quests[30435] = { id = 30435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Jogu", progress = "Kauft Ihr einem Jinyu was zu trinken?", completion = "Hey, das ist mein Lieblingsessen! Danke, {name}." }
quests[30436] = { id = 30436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Jadekatze für Jogu", progress = "Es ist harte Arbeit, wisst Ihr, all diese Visionen zu deuten.", completion = "Danke-" }
quests[30437] = { id = 30437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blaue Feder für Jogu", progress = "Die Ernte von morgen wird… oh, ich kann es noch nicht sehen. Erst muss ich etwas trinken.", completion = "Eine schöne blaue Feder für mich? Danke, {race}." }
quests[30438] = { id = 30438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sumpflilie für Jogu", progress = "Die Wascher schagen, dasch Euch heute das Glück hold schein wird.", completion = "Die Wascher hatten recht! Diesche Blume wird mir Glück bringen." }
quests[30439] = { id = 30439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gericht für Jogu", progress = "Wisst Ihr, was gut zu einem guten Schluck passt? Ein gutes Essen.", completion = "Nichts kommt an ein köstliches kaltes Getränk und ein paar gebratene Karotten heran." }
quests[30442] = { id = 30442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blanches Hammerbräu", description = "Helft beim Brauen von Blanches Hammerbräu, indem Ihr auf die Bierfässer aufpasst.", sourceObjective = "Helft das Hammerbräu zu brauen. Sollten die Bierfässer in Brand geraten, bringt das wieder in Ordnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[30444] = { id = 30444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Atempause", description = "Wir genießen gerade eine kurze Atempause von den Moguangriffe auf die Fünf Schwestern im Norden. Ich würde Euch gerne entsenden, um sicherzustellen, dass wir ihnen keine solche Ruhepause gewähren.\n\nZeigt keine Gnade.", sourceObjective = "Tötet 8 Shao-Tien-Mogu nahe den Fünf Schwestern.", completion = "Das sollte sie für eine Weile aus dem Konzept gebracht haben. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30445] = { id = 30445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wasser der Jugend", sourceObjective = "Überbringt Lyalia Vaeldrins Botschaft.", completion = "Er... er hätte das nicht machen sollen! Er hätte nicht für meinen Fehler bezahlen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30449] = { id = 30449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kranichkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Kranichkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Kranichkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Kranichkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Kranichkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30450] = { id = 30450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ochsenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Ochsenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Ochsenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Ochsenkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Ochsenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30451] = { id = 30451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Schlangenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Schlangenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Schlangenkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Schlangenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30452] = { id = 30452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Tigerkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Tigerkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Tigerkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Tigerkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30457] = { id = 30457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raus mit dem Anführer", description = "Eure Hilfe für uns ist wirklich heldenhaft.\n\nBitte tötet den Bataari-Stamm am Kun-Lai-Pass im Nordwesten, bis der Feuerkrieger der Bataari wütend genug ist, um aufzutauchen. Und dann erledigt auch ihn.", sourceObjective = "Tötet 10 Angehörige des Bataaristamms am Kun-Lai-Pass, bis der Feuerkrieger der Bataari auftaucht. Und dann tötet auch ihn.", completion = "Wir sind gerettet! Ich hatte immer Vertrauen in Euch und Eure Fähigkeiten als {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30458] = { id = 30458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Späher", description = "{name}, Eure Freunde sind von ihrer Spähermission zurückgekehrt. Ihr solltet sie sofort aufsuchen.\n\nIch bin besorgt...\n\nAber ich sage lieber nichts mehr. Seht es Euch selbst an.", sourceObjective = "Sprecht mit Rell Nachtwind im Perlflossendorf im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[30459] = { id = 30459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeile sammeln gehen", description = "Sobald ihre Verstärkungen eintreffen, werden die Yaungol unsere Positionen hier überrennen. Und wenn sie das tun, ist unser Dorf verloren.\n\nKönntet Ihr vielleicht so viele Pfeile wie möglich vom Schlachtfeld bergen? Ich habe einen Plan, der uns mit Eurer Hilfe vielleicht retten könnte.", sourceObjective = "Sammelt 12 Pfeile für Kommandantin Hsieh.", progress = "Wie viele Pfeile habt Ihr?", completion = "Ich danke Euch, {name}. Ihr habt unsere Verteidigungslinie hier gerettet.\n\nDieser nächste Angriff wäre ohne Eure Hilfe nicht möglich gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30460] = { id = 30460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Medizin", description = "Unsere Krieger kämpfen, um die Yaungol im Kun-Lai-Pass im Nordwesten im Zaum zu halten.\n\nNehmt dieses Einreibemittel. Es ist eine starke Medizin, deren Rezept in meiner Familie von einer Generation zur nächsten weitergegeben wurde.\n\nBenutzt die Dit Da Jow zur Heilung von verwundeten Kriegern, wenn Ihr keine eigenen Heilkräfte habt, die Ihr bei ihnen einsetzen könnt.", sourceObjective = "Benutzt die Dit Da Jow oder Eure eigenen Heilkräfte, um 8 verletzten Kriegern aus Binan zu helfen.", completion = "Habt meinen Dank, {name}. Ihr habt durch Eure Taten große Ehrbarkeit gezeigt.\n\nIch hoffe, die Dit Da Jow meiner Familie hat Euch etwas geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30461] = { id = 30461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wildnis", description = "Tief in der Wildnis liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger. Ich vermute, sie wissen etwas darüber, was hier passiert ist.\n\nDer Tempel befindet sich an der südlichen Küste der Wildnis, wo der Krasarang ins Meer mündet.", sourceObjective = "Findet Koro Nebelgänger in der Nähe des Tempels des Roten Kranichs an der südlichen Mündung des Krasarang.", completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Bastion besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30462] = { id = 30462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wildnis", description = "Tief in der Wildnis liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger\n\nIch vermute, sie wissen etwas darüber, was hier passiert ist.\n\nDer Tempel befindet sich an der südlichen Küste der Wildnis, wo der Krasarang ins Meer mündet.", sourceObjective = "Findet Koro Nebelgänger in der Nähe des Tempels des Roten Kranichs an der südlichen Mündung des Krasarang.", completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Bastion besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30464] = { id = 30464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Westen", description = "Leza wandelt nun mit den Vorfahren dieses seltsamen Landes. Ich muss mich jetzt um die Lebenden kümmern.\n\nKor hat eine Gruppe unserer Späher nach Westen tiefer in den Dschungel geführt.\n\nSpürt ihn auf und gebt ihm an Hilfe, was Ihr könnt. Wir werden so schnell wir können zu Euch stoßen.", sourceObjective = "Reist zur Morgenjägerzuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30465] = { id = 30465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Offensive gehen", description = "Ha! Also hat mein Vater zwanzig Jahre unserer Leben einer vergeblichen Mühe wegen verschwendet!\n\nIch übernehme das Kommando.\n\nAls Tyrande uns hierhergeschickt hat, machte sie sehr deutlich, dass wir nicht zurückkommen sollen, bis wir das Licht gefunden haben, das sie in ihren Visionen gesehen hatte. Es ist jetzt offensichtlich, dass es sich dabei nicht um die Teiche der Jugend gehandelt hat.\n\nWir rücken westwärts vor und könnten Eure Hilfe brauchen.\n\nTrefft Euch mit uns beim Lager der Schildwachen weiter im Westen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Lyalia beim Lager der Schildwachen in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[30466] = { id = 30466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genügend Motivation", description = "Die Ausbildung dieser Wilden war eine Herausforderung, {name}.\n\nSie zu motivieren war einfach, schwerer ist es jedoch, sie bei der Stange zu halten... sowie konzentriert... und wach.\n\nDa Ihr zurück seid, könnt Ihr mir helfen, die undisziplinierteren Ho-zen anzutreiben, wenn Ihr versteht, was ich meine. Ich überlasse Euch die Wahl der Methode.", sourceObjective = "Motiviert 10 Faule Ho-zen.", progress = "Sind die Ho-zen einsatzbereit?", completion = "Hrmm, ich wäre überrascht, wenn wir es schaffen würden, dass diese Kreaturen sich lange genug konzentrieren, um überhaupt eine Taktik anzuwenden, {name}.\n\nSie sollten besser nicht im Weg rumstehen, wenn die Klingen fliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30467] = { id = 30467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Sohn...", description = "Mein Sohn - könnt Ihr meinen Sohn suchen?\n\nAls die Jinyu angegriffen haben, rannte er verwirrt weg. Ich weiß nicht, ob sie ihm etwas angetan haben, geschweige denn, ob er überhaupt noch lebt.\n\nWenn ich ihn nicht finden kann, ist alles egal. \n\nIch würde Mei fragen... aber mit ihr stimmt etwas nicht. Seit dem Angriff scheint sie so... impulsiv zu sein. Ich kann einfach nicht darauf vertrauen, dass sie ihn sicher zurückbringt.", sourceObjective = "Findet Wu-Peng am Tintenkiemenweiher.", completion = "So schrecklich... Als ich das Morden sah, bin ich einfach nur gerannt. Mein Vater, Mei... sind sie am Leben?", sourceObjectiveStatus = "unverified-source-field" }
quests[30468] = { id = 30468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Vergeltung", description = "<Mit der Schwertmeisterin stimmt etwas nicht. Ihr Blick ist von einer Düsternis erfüllt, die für Pandaren ganz untypisch ist.>\n\nIch glaube nicht, dass ich jemals so... so wütend war. Oh dieser Verrat!\n\nIch schlug sie zurück, als sie angriffen, und konnte sogar ein paar von ihnen erledigen. Aber Händler Shi ist ein solcher Feigling, dass er mir nicht erlaubt, sie zu verfolgen und meine Arbeit zu Ende zu bringen!\n\nIhr! Ihr werdet es für mich tun. Ihr werdet sie alle ausschalten!", sourceObjective = "Tötet 15 wütende Jinyu.", completion = "Es ist befriedigend zu hören, dass unsere Feinde tot sind. Vielleicht könnt Ihr eine der Waffen meines Leibwächters brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30469] = { id = 30469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederinbesitznahme", description = "Natürlich liegt die oberste Priorität darauf, meinen Sohn zu finden. Wenn wir uns selbst aber nur retten, um zu verhungern, was haben wir dann am Ende erreicht?\n\nBitte, ich brauche Euch, um einige der Vorräte wiederzubeschaffen, die die Jinyu unserer Karawane geraubt haben.", sourceObjective = "Sammelt 8 gestohlene Versorgungsgüter.", progress = "Habt Ihr die Vorräte gefunden?", completion = "Danke... jetzt endlich können wir etwas essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30470] = { id = 30470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Tina", description = "Tina Lehmkrall ist heute auf dem Halbhügelmarkt und besucht ihre Schwester. Ihre Familie hat mir wirklich sehr geholfen und ich möchte mich dafür revanchieren.\n\nIn den Klippen im Norden kann man einen kleinen Edelstein finden. Wir nennen ihn Chrysoberyll und er ändert seine Farbe, wenn man ihn in der Hand hält. SO EINEN hat sie bestimmt noch nicht!\n\nSucht in den Shed-Ling-Höhlen danach. Ich bin sicher, Ihr findet schnell einen.", sourceObjective = "Findet einen rohen Chrysoberyll.", progress = "Hallo, {name}! Schön, Euch mal wieder zu sehen.", completion = "<Tina hält den Stein in der Hand und beobachtet, wie seine Farbe von fahlem Blau zu leuchtendem Rot wechselt.>\n\nEin Chrysoberyll? Das ist ja reizend! Und das war Andis Idee?\n\nNatürlich habe ich schon einige davon... Aber der hier ist auch wunderschön. Der wird sich gut in meiner Sammlung machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30471] = { id = 30471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Chi-Chi", description = "Dieser verrückte Chi-Chi ist eigentlich gar nicht so übel. Mah sagte immer, die Ho-zen machen nichts als Ärger, aber... vielleicht ist er auch nur ein anständigerer Ho-zen als die anderen.\n\nWir sollten ihm einen Gefallen tun. Die Ho-zen in den Bergen im Westen bereiten ein aufwendiges Pfannengericht zu und bewahren oft Schüsseln davon in ihren Ho-zen-Hütten auf.\n\nIch wette, dass Chi-Chi liebend gerne etwas davon hätte!", sourceObjective = "Besorgt ein authentisches Pfannengericht nach Vier-Winde-Art.", completion = "Für mich? Extra für Chi-Chi?\n\nDas ist wie früher, als Chi-Chi noch ein mubbeliges Baby war. Chi-Chis Mama hat das genauso gekocht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30472] = { id = 30472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Sho", description = "Sho, dieses Mädchen, das oben in den Bergen lebt, ist heute in der Stadt. Ich habe gesehen, dass sie in Richtung Halbhügelmarkt ging.\n\nSo ein langer Weg... Sie muss hungrig sein. Und ich glaube, ich weiß genau, was ihr gefallen würde.\n\nDie Ho-zen oben auf der Himmelsweite kochen eine Suppe aus Fischen und Äpfeln. Ich weiß, das klingt nach einem seltsamen Gericht, aber es ist wirklich köstlich. Ihr könnt es in der Nähe ihres großen, furchteinflößenden Totems finden.", sourceObjective = "Besorgt eine Schüssel Yu-Ping-Suppe.", progress = "Oh! Hallo, {name}.", completion = "Ich war so hungrig! Wie konntet Ihr das wissen? Wer hat es Euch verraten?\n\nAndi? Hm, der Junge wird noch mal ein richtiger Herzensbrecher...", sourceObjectiveStatus = "unverified-source-field" }
quests[30473] = { id = 30473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Fischi", description = "Diese Fischi Rohrroder ist schon irgendwie seltsam. Schon allein ihr Name - Fischi. Das sollte mir zu denken geben.\n\nAber wenn man erst mal mit ihr spricht, merkt man, dass sie wirklich nett ist. Wusstet Ihr zum Beispiel, dass sie Tiere über alles liebt?\n\nDas bringt mich auf eine Idee. Die Kunzen-Ho-zen in den Bergen im Westen schnitzen Tierstatuen und platzieren sie in ihren Hütten, um Feinde abzuwehren. Ich wette, Fischi würde so was einfach LIEBEN!", sourceObjective = "Besorgt eine Yakstatuette aus einer Hütte der Kunzen-Ho-zen.", progress = "Hey, {name}! Wie geht's denn?", completion = "Oh, wie schön! Wie WUNDERSCHÖN! Mit dem kleinen pelzigen Schwanz und...\n\n<Sie wird wieder ernst.>\n\nIch meine, ähem... danke, mein Lieber. Ist wirklich ganz reizend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30474] = { id = 30474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Ella", description = "Arme Ella. Sie ist so schüchtern. Ich habe gesehen, wie sie auf dem Halbhügelmarkt stand und enorm hungrig aussah. Aber sie hat sich nicht getraut, einen der Köche anzusprechen.\n\nWir sollten ihr etwas zu essen bringen. Aber nicht irgendetwas, sondern etwas Besonderes.\n\nDie Kunzen-Ho-zen machen aus den Waren, die sie uns Bauern klauen, pikante Garnelenklößchen. Die würden Ella ganz sicher gefallen.", sourceObjective = "Besorgt pikante Garnelenklößchen.", progress = "Oh, also ... hallo.", completion = "Das wäre doch nicht nötig gewesen! Ich wollte doch gar nicht, ich brauch doch gar nicht...\n\n<Ella sieht die Klöße und das Wasser läuft ihr im Mund zusammen.>\n\nAlso, ja, vielleicht war ich etwas hungrig. Danke, {name}. Und richtet bitte auch Andi meinen Dank aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30475] = { id = 30475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Fung", description = "Bauer Fung kann ganz schön ungehobelt sein. Er jagt mir wirklich Angst ein. Aber Mah sagte immer, dass er einer der besten Landwirte im Tal sei.\n\nIch glaube, ich kenne das perfekte Geschenk für so einen gemeinen, Furcht einflößenden Kerl wie ihn.\n\nÜber den Hügeln westlich von hier kreisen ein paar kapitale Ebenenfalken. Ihr solltet einen davon erlegen, ein gutes Stück Fleisch rausschneiden und Kol Eisentatz bitten, es zu grillen!", sourceObjective = "Beschafft ein blutiges Ebenenfalkenbein von einem monströsen Ebenenfalken und bringt es dann zu Kol Eisentatz auf dem Halbhügelmarkt.", progress = "Mmh-mmh…", completion = "Hey! Wo habt Ihr das denn her? Das könnte ja von einem Ebenenfalken sein!\n\nAndi hat Euch damit zu mir geschickt? Ha, vielleicht habe ich den Jungen doch unterschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30476] = { id = 30476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den alten Hügelpranke", description = "Der alte Hügelpranke hat Millionen von Hühnern auf seinem Hof. Aber die sind ihm gar nicht SO wichtig.\n\nIch weiß nämlich, dass er am liebsten blaue Federn sammelt.\n\nIch habe keine Ahnung, wo man hier in der Gegend blaue Federn findet, aber ich weiß, wo es blaue Perlen gibt!\n\nSucht in den Austern des Rohrkolbensees im Nordwesten. Ich wette, er würde eine blaue Perle als Ergänzung zu seiner Sammlung sehr zu schätzen wissen.", sourceObjective = "Findet eine blaue Süßwasserperle.", progress = "{name}! Ihr habt mich erschreckt.", completion = "Jetzt sieh sich die mal einer an! Die muss ich irgendwo aufbewahren, wo die Hühner nicht rankommen.\n\nUnd Andi hat Euch aufgetragen, die für mich zu besorgen? Netter Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[30477] = { id = 30477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Haohan", description = "Haohan Lehmkrall ist der Vorsitzende des Bundes der Ackerbauern und der reichste Landbesitzer des Tals. Es war sehr nett von ihm, mich hier willkommen zu heißen, und ich möchte ihm im Gegenzug auch einen Gefallen erweisen.\n\nEr hat einen sehr exklusiven Geschmack - er sammelt Rubinsplitter und solche Sachen. Aber ich habe nicht besonders viel Geld, also muss es etwas anderes sein...\n\nIch weiß! Ich habe einen gewaltigen Fisch im Rohrkolbensee entdeckt! Wir sollten ihm einen Zahn von diesem Fisch als Geschenk besorgen!", sourceObjective = "Besorgt den Zahn eines gewaltigen Rohrkolbenbarschs.", progress = "Kann ich etwas für Euch tun, {class}?", completion = "Was haben wir denn da?! SO einen Zahn sieht man auch nicht alle Tage.\n\nHabt Ihr etwa Haie gejagt, {class}?\n\nIch danke Euch, {name}. Und richtet bitte auch Andi meinen Dank aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30478] = { id = 30478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Jogu", description = "Manchmal tut mir Jogu richtig leid. Er ist der einzige Jinyu hier und er hat offensichtlich nicht viele Freunde. Von seiner stinkigen Flasche mal abgesehen, versteht sich.\n\nWisst Ihr was? Ich habe da eine Idee. Bauer Yoon hat noch einen Korb Kranichbeeren im Haus und auch noch ein paar Äpfel. Die könntet Ihr doch zum Destilliermeister auf dem Halbhügelmarkt bringen und daraus ein leckeres Tröpfchen für Jogu brennen lassen.", sourceObjective = "Bringt 8 von Yoons Äpfeln und 50 seiner Kranichbeeren zu Bobo Eisentatz, um daraus Apfelbeerenfusel brennen zu lassen.", completion = "<Jogu nimmt einen großen Schluck von dem Fusel.>\n\nDasch isch fantaschtisch! Mein neuer Lieblingschfuschel. Der hier und schonscht keiner!\n\nWischt Ihr wasch, {name}? Ihr scheid schwer in Ordnung! Wirklisch wahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[30479] = { id = 30479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Gina", description = "Habt Ihr schon Gina Lehmkrall, das Mädchen auf dem Markt, gesehen? Sie ist perfekt: gut aussehend, intelligent und mit einem süßen, dicken Bauch ausgestattet. Würdet Ihr ihr ein Geschenk von mir bringen?\n\nIch wollte ihr gern ein paar Orchideen pflücken, die auf den höchsten Hügeln im Westen wachsen, aber so hoch komme ich einfach nicht. Könntet Ihr vielleicht eine davon pflücken und sie Gina bringen?\n\nOh, und wenn Ihr sie seht, dann grüßt sie bitte von mir.", sourceObjective = "Findet eine Goldfeuerorchidee.", progress = "Hallo!", completion = "Die ist ja herrlich! Ist die etwa für mich?\n\nAhh... von Andi ist sie also, ja? Ich glaube, ich kenne da jemanden, der heute Nachmittag einen dicken Kuss auf die Stirn bekommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[30480] = { id = 30480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual", description = "Schon als ich zum ersten Mal aus dem Fluss stieg, wusste ich, dass es mir beschieden war, Wassersprecher zu werden.\n\nIch wurde viele Rituale gelehrt, und alle von ihnen habe ich schon durchgeführt, außer einem.\n\nEs gab da ein sehr altes Ritual, das für eine Zeit gedacht war, wenn sich unser Volk je gegen uns wenden sollte.\n\nSo etwas muss sich in der fernen Vergangenheit unseres Volkes ereignet haben, denn solange die Erinnerung unseres Dorfes zurückreicht, ist das niemals nötig gewesen.\n\nJetzt ist wohl die Zeit dafür gekommen.", sourceObjective = "Sprecht mit Wassersprecher Gorai und beendet dann das Ritual.", completion = "Jetzt verstehe ich, dass dieses Ritual fortreißt, was auch immer die Geister dieser Kreaturen kontrolliert. Jetzt weiß ich, was wir tun müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30481] = { id = 30481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stein gemeißelt", description = "Ihr seht Glitzersteine in Mauern? Rook will welche. Die Mogu haben sie auch gesammelt. Vielleicht haben die auch ein paar.\n\nWenn Ihr Steine findet, bringt Ihr sie Rook? Rook wird Euer Freund sein.", sourceObjective = "Sammelt 12 Guo-Lai-Runensteine zusammen.", progress = "Ihr habt Steine für Rook? Bitte?", completion = "So viele! Und so glitzerig! Sehr gut!\n\nIch danke Euch, kleiner Freund. Rook mag Euch sehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[30482] = { id = 30482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelensammler", description = "Während Ihr noch dabei wart, den einen Mogu zu töten, bemerktet Ihr einen anderen großen Mogu, der ein Ritual ausführte. Er wäre vielleicht nicht so klug, ihn sein Ritual beenden zu lassen.", sourceObjective = "Tötet Schattenmeister Sydow und sichert Euch seine Seelenperlen.", progress = "<Er schaut Euch erwartungsvoll an.>", completion = "<Als Ihr Hee die Perlen gebt, lässt sein Lächeln darauf schließen, dass er genau weiß, was sie symbolisieren. Er nickt anerkennend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30484] = { id = 30484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messung unseres Fortschritts", description = "Der Krieg steht kurz bevor, {name}!\n\nWir haben die Einheimischen ohne Unterbrechung ausgebildet, seit Ihr aufgebrochen seid, und ich denke, dass sie nun so gut sind, wie sie es jemals sein können.\n\nAber seht selbst. Besucht die anderen und kehrt mit Euren Ergebnissen zurück.\n\nWir müssen uns darauf verlassen, dass der Feind... noch weniger vorbereitet ist.", sourceObjective = "Besucht Schattenmeisterin Kiryn, Nieti Kuppelplopp, Shokia und Riko.", progress = "Wie läuft es mit unserer Kampfausbildung?", completion = "Wenigstens sind sie zuversichtlich.\n\nDas ist doch die Hauptsache.", sourceObjectiveStatus = "unverified-source-field" }
quests[30485] = { id = 30485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Puzzleteil", description = "Diese Ho-zen verhalten sich höchst unnatürlich, {name}. Marschieren in Formation? Und in Rüstung?\n\nDas beunruhigt mich. Allerdings müssen wir das zu einem anderen Zeitpunkt besprechen. Ich bin hier, um Euch um Eure Unterstützung zu bitten.\n\nDas uralte Fresko, dort, wo wir uns zuletzt unterhielten, ist fast enthüllt. Ich bin mir sicher, dass es uralte Weisheit enthält - Weisheit, von der der Kaiser wollte, dass wir sie nicht vergessen.\n\nDurch Meditation allein kann ich ihre Bedeutung vielleicht nicht rechtzeitig enthüllen. Bitte, bringt dieses Erbstück zum Schrein meiner Ahnen. Mit ihrer Hilfe werden wir dieses Rätsel lösen können.", sourceObjective = "Benutzt Chos Erbstück bei Chos Familienschrein beim Schlangenblick.\n\nUm dorthin zu kommen, sprecht mit Mishi.", completion = "<Lehrensucher Cho schüttelt sich unwillkürlich.>\n\nDie Legenden… sie sind wahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[30487] = { id = 30487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über den Bergpass", description = "Der Bergpass ist sehr gefährlich. Ihr braucht viel Glück, um zu überleben. Neffe Krummnagel zeigt Euch den Weg.\n\nAber vielleicht ist heute ein Glückstag für Reisen. Wind kommt aus Osten; ist gutes Zeichen. Grummel reisen am besten bei Ostwind.\n\nKlettert in den Wagen, wenn Ihr zum Aufbruch bereit seid.", sourceObjective = "Bringt den Wagen und die Wagenführer sicher durch das Nimmerlaya-Gebirge.", completion = "Ihr seid gerade rechtzeitig eingetroffen, {class}! Ich dachte schon, ich würde hier oben sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30488] = { id = 30488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschwundene Moschuspranken-Spross", description = "Was zur Hölle seid Ihr denn? <Ein/Eine:c> {class}? Nie gehört. Seid Ihr hier, um zu helfen oder um mir meine Yaks zu stehlen?\n\nHört mal, wenn Ihr mir schon unbedingt helfen wollt, dann seht zu, ob Ihr nicht meinen Jungen findet. Er wurde von 'ner Horde Geister geschnappt und weiß wahrscheinlich nicht mal, dass wir den Hof verloren haben.\n\nSie haben ihn zum Witzboldwinkel im Südosten geschleppt. Rettet ihn, und ich werd' sehen, ob ich 'ne Belohnung für Euch auftreiben kann.", sourceObjective = "Findet Moschuspranke Jr. im Witzboldwinkel.", completion = "Danke für die Rettung, Fremder!", sourceObjectiveStatus = "unverified-source-field" }
quests[30489] = { id = 30489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frischer Nadelduft", description = "Wenn Ihr mir wirklich helfen möchtet, könntet Ihr mir einige Nadeln von den Waldgeistern im Witzboldwinkel besorgen.\n\nDie Grummel glauben nur an Glück, das sie auch riechen können. Sie zahlen besser für Yaks mit einem frischen Nadelgeruch.", sourceObjective = "Sammelt 100 geruchsintensive Waldgeisternadeln ein.", progress = "Ah! Geht doch nichts über den frischen Geruch von Nadeln.", completion = "Ihr habt mir zu einem schönen Bonus verholfen. Diese Nadeln zu besorgen ist harte Arbeit, aber eine gute Investition, bevor wir die Yaks zum Markt bringen. Bitte nehmt dies hier für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30490] = { id = 30490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände weg von meinen Yaks!", description = "Yaungol! Die kommen an, nehmen sich, was sie wollen, und machen den Rest kaputt.\n\nIch kann nicht zulassen, dass diese Rohlinge den letzten Rest der Yaksalberei hier zerstören. Das ist alles, was meinem Jungen und mir geblieben ist.\n\nGeht rüber zu unserem alten Hof und gebt den Yaungol ordentlich was auf die Futterluke. Ich wette, wenn Ihr genug von denen erledigt, überlegen sie es sich zweimal, bevor sie hier nochmal angreifen.", sourceObjective = "Tötet 9 Räuber der Burilgi auf dem Gehöft Moschuspranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[30491] = { id = 30491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Yaksalberei", description = "Mein Vater ist einfach verrückt. Ich liebe ihn, aber er ist nun mal verrückt.\n\nDiese Yaungol haben unseren Hof vollständig auseinander genommen und unsere Yaks in alle Windrichtungen vertrieben.\n\nAber wie ich meinen Vater kenne, wird er sich in den Kampf gegen die Yaungol stürzen, um die Yaks zurückzubekommen.\n\nKönntet Ihr uns helfen und einige der Yaks zusammentreiben, damit mein Vater keine Dummheiten anstellt?\n\nTreibt sie einfach rüber zur Yaksalberei, damit wir sie sauber machen und an die Grummel verkaufen können.", sourceObjective = "Bringt 6 entlaufene Yaks zum Eingang der Yaksalberei Lao & Sohn.", completion = "Gut gemacht, Fremder! Hoffentlich bekommen wir gutes Geld für sie, damit wir einige der Schäden kompensieren können, die die Yaungol angerichtet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30492] = { id = 30492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauberes Yak, gutes Yak", description = "Ich habe nicht gelogen, als ich über Eure Belohnung sprach. Hier, bitte führt diese Yaks zum Karawanenführer Achtgroschen.\n\nIhr findet ihn auf dem Grummelbasar westlich von hier. Er wird für sie bezahlen und Euch auch einen kleinen Lohn für die Lieferung geben.\n\nEr ist von kleiner Statur, aber unser größter Kunde.\n\nKehrt zu mir zurück, wenn Ihr die Yaks verlieren solltet. Meistens laufen sie dann sowieso wieder direkt hierher zurück. Aber natürlich erst, wenn sie gewaschen sind.", sourceObjective = "Bringt die gewaschenen Yaks zu Achtgroschen dem Glückspilz auf dem Grummelbasar am Kun-Lai-Gipfel. Kehrt zu Moschuspranke Jr. zurück, solltet Ihr die Yaks verlieren.", completion = "Ah! Ich kann das Glück von hier aus riechen. Die Moschuspranken haben immer gute Yaks zum Verkauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[30495] = { id = 30495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebesdienst", description = "Kann ich Euch um einen weiteren Gefallen bitten?\n\nWir liegen im Zeitplan zurück, und diese Jadelieferung ist die letzte, die zur Vollendung der großen Statue fehlt.\n\nIch habe alle Hände voll zu tun, könntet Ihr das Erz vielleicht zu den anderen Vorarbeitern bringen?\n\nIhr findet Historiker Dinh, Feldmesser Sawa und Drachenmeister Shoku am Fuße der Statue. Bauleiterin Emi leitet die Produktion an der Spitze der Statue.\n\nWir haben nicht mehr viel Zeit, also beeilt Euch! Die Zeit ist knapp!", sourceObjective = "Bringt die Jade zu Historiker Dinh, Feldmesser Sawa, Drachenmeister Shoku und Bauleiterin Emi.", completion = "Was, schon erledigt? Ihr seid wirklich schnell, {class}. Habt Ihr je überlegt, damit Euren Lebensunterhalt zu verdienen?", sourceObjectiveStatus = "unverified-source-field" }
quests[30496] = { id = 30496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab des Wassersprechers", description = "Es herrscht große Uneinigkeit am Tintenkiemenweiher, {race}. Der Älteste Shai Hu hat vom Sha-verderbten Wasser des Weihers getrunken und die anderen gezwungen, es ihm gleichzutun. Als ich protestierte, hat Orachi von der Stadtwache meinen Ritualstab konfisziert und mich verbannt.\n\nNun bin ich nicht nur im Exil, sondern kann überdies auch nicht mehr mit den Wassern reden, die mir einst Rat spendeten!\n\nIch bin kein Kämpfer, aber Ihr... vielleicht könnt Ihr ja Orachi meinen Stab entreißen? Ihr findet ihn in der Stadt nördlich von hier.", sourceObjective = "Holt Wassersprecher Gorais gestohlenen Ritualstab der Tintenkiemen von Orachi am Tintenkiemenweiher zurück.", progress = "Habt Ihr den Stab gefunden?", completion = "Gut. Dann können wir dieses Problem vielleicht doch noch lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30498] = { id = 30498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt zurück!", description = "Oh, bevor ich es vergesse, ich habe hier etwas, das ich Euch übergeben soll. Ein Brief von einem Eurer Kameraden, nehme ich an.\n\nMan hat mir zu verstehen gegeben, dass Eure Anwesenheit dringendst erforderlich ist, deshalb habe ich mir die Freiheit genommen, Eure Reise vorzubereiten.\n\nSprecht mit Ginsa Pfeilauge, direkt südlich von hier, wenn Ihr bereit seid. Sie hat einen Drachen für Euch.", sourceObjective = "Meldet Euch bei Admiral Taylor im Dorf der Perlflossen.\n\nBereitgestellter Gegenstand:", completion = "Willkommen zurück, {name}. Ich gehe davon aus, dass Ihr bei Eurer Reise neue Eindrücke gewinnen konntet, insbesondere hinsichtlich der Beschaffenheit des Landes. Es gibt noch viel zu tun, bevor wir in die Schlacht ziehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30499] = { id = 30499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt zurück!", description = "Oh, bevor ich es vergesse, ich habe hier etwas, das ich Euch übergeben soll. Ein Brief von einem Eurer Kameraden, nehme ich an.\n\nMan hat mir zu verstehen gegeben, dass Eure Anwesenheit dringendst erforderlich ist, deshalb habe ich mir die Freiheit genommen, Eure Reise vorzubereiten.\n\nSprecht mit Ginsa Pfeilauge, direkt südlich von hier, wenn Ihr bereit seid. Sie hat einen Drachen für Euch.", sourceObjective = "Kehrt zu General Nazgrim auf dem Flotschhügel zurück.\n\nBereitgestellter Gegenstand:", completion = "Throm-Ka, {name}! Ich hoffe, Ihr konntet bei Eurer Reise durch den Wald nützliche Informationen sammeln.\n\nUnsere Vorbereitungen sind fast abgeschlossen, aber wir benötigen noch Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30500] = { id = 30500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negative Konsequenzen", description = "Pandaria ist ein mystisches Land, <Reisender/Reisende>.\n\nEs kann nicht oft genug wiederholt werden, dass einige seiner Geheimnisse selbst Lehrensuchern verborgen sind.\n\nDas Schließen dieser Risse hat nicht geheilt, was zerbrochen war.\n\nSollten die Sagen wahr sein, so bedarf es sehr viel mehr, um dieses Land dem Griff des Sha zu entreißen.\n\nDie aggressiven Emotionen aus dem Kampf haben einen Schwarm von lebenden negativen Gefühlen geweckt. Was Ihr hier seht, sind vermutlich die ersten von vielen dieser Manifestationen.\n\nFür den Moment können wir nichts anderes tun, als zu versuchen, ihre Präsenz zu verringern.", sourceObjective = "Vernichtet 10 Sha-Echos.", completion = "Das ist schrecklich…\n\nWir müssen einen Weg finden, um das, was hier geschehen ist, wieder rückgängig zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30501] = { id = 30501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gossip Accept Quest Test Case" }
quests[30502] = { id = 30502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz", description = "Die mächtigeren Rückstände der schrecklichen Manifestation sind vielleicht zu stark, als dass Ihr Euch alleine darum kümmern könntet, {name}.\n\nIch fürchte, ich kann Euch nur wenig im echten Kampf unterstützen, aber ich kann Euch eine Lösung vorschlagen.\n\nDie große Jadestatue sollte schon bald eine lebendige Schlange werden - eine unserer verehrten Himmlischen. Ihre Erschaffung hat sie mit besonderen Kräften erfüllt, die diese Gegner ausreichend schwächen könnten.", sourceObjective = "Benutzt Brocken himmlischer Jade, um 6 Sha-Rückstände zu vernichten.", completion = "<Cho blickt Euch niedergeschlagen an.>\n\nDiese Jade war für… so viel mehr gedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30504] = { id = 30504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallplan", description = "Eure Kameraden haben sich in unseren Landen eine neue Heimat errichtet und einen gefährlichen Zwist mit sich gebracht.\n\nDas volle Ausmaß der Vernichtung können wir hier noch nicht abschätzen, doch bereits jetzt ist es… unaussprechlich.\n\nUnd doch, Eure Freunde aus Rachegefühlen sich selbst zu überlassen, würde unserer Art zu leben widersprechen. Jeder, der jetzt noch am Leben ist, ist zweifelslos verwundet und bedarf dringend Hilfe.\n\nDieses Feuerwerk war eigentlich dazu gedacht, die Fertigstellung der Statue zu feiern. Benutzt es in der Nähe Eurer Kameraden, um Mishi ein Zeichen zu geben, und sie wird sie in Sicherheit bringen.", sourceObjective = "Benutzt Chos Feuerwerk in der Nähe von General Nazgrim, Schattenmeisterin Kiryn, Shokia und Nieti Kuppelplopp.", completion = "Mit meinen Gedanken bin ich bei Euren gefallenen Begleitern, Reisender.\n\nMögen ihre Wunden gut heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30506] = { id = 30506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor ist erwacht", description = "Anscheinend ist Euer Admiral Taylor von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus des Apothekers in Binan.\n\nEr hat nach Eurer Anwesenheit verlangt.", sourceObjective = "Sprecht mit Admiral Taylor in Binan am Kun-Lai-Gipfel.", completion = "{name}, seid Ihr das? Ich kann gar nicht glauben, dass wir die Vernichtung der Jadeschlange überlebt haben.\n\nZumindest einige von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[30507] = { id = 30507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor ist erwacht", description = "Anscheinend ist Euer Admiral Taylor von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus des Apothekers auf der anderen Straßenseite.\n\nEr hat nach Eurer Anwesenheit verlangt.", sourceObjective = "Sprecht mit Admiral Taylor in Binan am Kun-Lai-Gipfel.", completion = "{name}, seid Ihr das? Ich kann gar nicht glauben, dass wir die Vernichtung der Jadeschlange überlebt haben.\n\nZumindest einige von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[30508] = { id = 30508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor ist erwacht", description = "Anscheinend ist Euer Admiral Taylor von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben.\n\nEr hat nach Eurer Anwesenheit verlangt.", sourceObjective = "Sprecht mit Admiral Taylor in Binan am Kun-Lai-Gipfel.", completion = "{name}, seid Ihr das? Ich kann gar nicht glauben, dass wir die Vernichtung der Jadeschlange überlebt haben.\n\nZumindest einige von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[30509] = { id = 30509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim ist erwacht", description = "Anscheinend ist Euer General Nazgrim von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus der Apothekerin in Binan.\n\nEr hat nach Eurer Anwesenheit verlangt.", sourceObjective = "Sprecht mit General Nazgrim in Binan am Kun-Lai-Gipfel.", completion = "Wo seid Ihr gewesen, {name}? Schon gut. Wie Ihr sehen könnt, haben wir den Kampf bei der Jadeschlange überlebt.\n\nUnglücklicherweise... sie auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30510] = { id = 30510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim ist erwacht", description = "Anscheinend ist Euer General Nazgrim von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus der Apothekerin auf der anderen Straßenseite.\n\nEr hat nach Eurer Anwesenheit verlangt.", sourceObjective = "Sprecht mit General Nazgrim in Binan am Kun-Lai-Gipfel.", completion = "Wo seid Ihr gewesen, {name}? Schon gut. Wie Ihr sehen könnt, haben wir den Kampf bei der Jadeschlange überlebt.\n\nUnglücklicherweise... sie auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30511] = { id = 30511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim ist erwacht", description = "Anscheinend ist Euer General Nazgrim von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben.\n\nEr hat nach Eurer Anwesenheit verlangt.", sourceObjective = "Sprecht mit General Nazgrim in Binan am Kun-Lai-Gipfel.", completion = "Wo seid Ihr gewesen, {name}? Schon gut. Wie Ihr sehen könnt, haben wir den Kampf bei der Jadeschlange überlebt.\n\nUnglücklicherweise... sie auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30512] = { id = 30512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westwindruhestätte", description = "<Admiral Taylor zuckt schmerzerfüllt zusammen.>\n\nDer Jadewald war eine Katastrophe. Anduin ist weg und wir haben gute Leute verloren. Wir haben nicht verhindert, dass die Horde weiter in den Kontinent vorrückt.\n\nAber ich glaube, ich habe eine Methode gefunden, um die Bevölkerung hier auf unsere Seite zu bringen. Ihr habt ihnen ja bereits geholfen, diese \"Yaungol\" abzuwehren, nicht wahr?\n\nIch habe gehört, dass die Yaungol die Westwindruhestätte, ein nahes Dorf, überfallen haben. Man sagt, dass zwei Gruppen von Überlebenden bei der Straße lagern, die nach Westen aus dem Ort führt.\n\nWenn wir ihnen helfen, ziehen sie es vielleicht in Betracht, sich der Allianz anzuschließen.", sourceObjective = "Sprecht mit Landarbeiter Bo und dem Ältesten Tsulan beim Yaungolvorstoß.", progress = "Ich werde erst ruhen, wenn mein Volk zurückgekehrt und dieses Dorf wiederaufgebaut ist.", completion = "Nun... wir leben und es geht uns besser als es ohne Eure Hilfe möglich gewesen wäre.\n\nAber wenn Ihr hier eine Operationsbasis errichten wollt und wir der Allianz beitreten sollen, dann müsst Ihr unsere Sicherheit gewährleisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30513] = { id = 30513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ostwindruhestätte", description = "Ich bin zwar verwundet, aber wir können nicht einfach aufhören.\n\nDie Ho-zen haben sich als... unzuverlässig herausgestellt. Die Pandaren wären viel bessere Verbündete.\n\nIch bin mir sicher, dass Ihr die Flüchtlinge in diesem Dorf gesehen und von der Yaungolinvasion gehört habt.\n\nNun, wir haben von den Einheimischen gehört, dass die Ostwindruhestätte, ein Dorf in der Nähe, von den Yaungol zerstört worden ist.\n\nAnscheinend haben einige Überlebende sich an der Straße, die aus dem Ort führt, versammelt.\n\nGeht. Nehmt die Straße nach Westen. Versammelt die Überlebenden.\n\nWir werden sie beim Wiederaufbau unterstützten. Dann werden sie erkennen, welche Vorteile es hat, sich der Horde anzuschließen!", sourceObjective = "Sprecht mit Landarbeiter Ko und dem Ältesten Shiao am Kun-Lai-Gipfel", completion = "Nun... wir sind am Leben und das ist mehr, als wir ohne Eure Hilfe erhoffen durften.\n\nDoch bevor hier eine Operationsbasis für Euch entstehen kann und wir uns Eurer Horde anschließen, müsst Ihr noch eines tun, um unsere Sicherheit zu garantieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30514] = { id = 30514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gipfelherausforderung", description = "Die Yaungol waren zwar schon immer ein schwieriges, stolzes Volk, aber nie dermaßen gewalttätig oder aggressiv. \n\nIch weiß nicht, was diese Verhaltensänderung veranlasst hat, aber momentan haben wir keine Zeit, um den Grund dafür herauszufinden. Wir fürchten um unser Leben und unser Auskommen, solange Ul-Bataar, der Anführer der Bataariyaungol, am Leben ist.\n\nLos, setzt das Banner in seinem Lager in Brand, um ihn herauszufordern, und besiegt ihn dann im Kampf. Erst dann werden wir sicher sein.", sourceObjective = "Setzt das Yaungolbanner in Flammen, um Ul-Bataar herbeizulocken, und besiegt ihn anschließend im Kampf.", progress = "Solange Ul-Bataar am Leben ist, wird es keinen Frieden geben.", completion = "Ihr habt es geschafft! Wenigstens hat die Gerechtigkeit gesiegt und wir sind nun sicher, aber auf dem Weg dorthin haben wir viel verloren.\n\nWie dem auch sei, es ist entschieden. Wir werden der Allianz beitreten und mit Eurer Hilfe dieses Dorf wieder aufbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30515] = { id = 30515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gipfelherausforderung", description = "Die Yaungol waren zwar schon immer ein schwieriges, stolzes Volk, aber nie dermaßen gewalttätig oder aggressiv. \n\nIch weiß nicht, was diese Verhaltensänderung veranlasst hat, aber momentan haben wir keine Zeit, um den Grund dafür herauszufinden. Wir fürchten um unser Leben und unser Auskommen, solange Ul-Bataar, der Anführer der Bataariyaungol am Leben ist.\n\nLos, setzt das Banner in seinem Lager in Brand, um ihn herauszufordern, und besiegt ihn dann im Kampf. Erst dann werden wir sicher sein.", sourceObjective = "Setzt das Yaungolbanner im Streitlager Bataar in Flammen, um Ul-Bataar herbeizulocken, und besiegt ihn anschließend im Kampf.", progress = "Solange Ul-Bataar am Leben ist, wird es keinen Frieden geben.", completion = "Ihr habt es geschafft! Wenigstens hat die Gerechtigkeit gesiegt und wir sind nun sicher, aber auf dem Weg dorthin haben wir viel verloren.\n\nWie dem auch sei, es ist entschieden. Wir werden der Horde beitreten und mit Eurer Hilfe dieses Dorf wieder aufbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30516] = { id = 30516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hof pflegen I: Ein kleines Problem", description = "Ihr müsst garstiges Unkraut beseitigen?\n\nKein Problem! Allerdings habe ich kaum noch Unkrautvernichter.\n\nIch habe da ein Eigengebräu - äußerst effektiv, komplett biologisch, gut für den Boden, die Pflanzen lieben es... nun... natürlich nicht dieses miese Unkraut! Das hat keine Chance!\n\nWenn Ihr mir etwas Spinnenwurz von den Terrassen westlich von uns bringen könnt, kann ich einen frischen Vorrat herstellen und persönlich Yoons Hof aufsuchen.\n\nIch würde es ja gerne selbst holen, aber... nun... ich hasse Spinnen. Ihr werdet verstehen, was ich meine.", sourceObjective = "Sammelt 6 Spinnenwurz für Gai Lan.", progress = "Wie ist es mit dem Wurzelsammeln gelaufen?", completion = "Na, was haben wir denn da? Das wird eine Weile reichen.\n\nVielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[30517] = { id = 30517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer Fungs Stimme I: Yakangriff", description = "Das nächste stimmberechtigte Mitglied des Bundes der Ackerbauern ist Bauer Fung, was nicht verwunderlich ist.\n\nSein Gemüse ist nämlich das größte im ganzen Tal! Ich hoffe, dass ich eines Tages so große Kürbisse züchten kann wie er.\n\nWenn wir den Ackerbauern beitreten wollen, ist er der Nächste, den wir überzeugen müssen.", sourceObjective = "Sprecht mit Bauer Fung im Kernland oder auf dem Halbhügelmarkt im Tal der Vier Winde.", completion = "Oh? Ihr seid doch bei diesem neuen Bauern in der Stadt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[30518] = { id = 30518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer Fungs Stimme II: In freier Wildbahn", description = "Ihr wollt meine Stimme für Bauer Yoon? Hah! Das soll wohl ein Witz sein, oder?\n\nPasst auf, ich werde einer Stadtpfote, die überhaupt keine Ahnung von Landwirtschaft hat, bestimmt keine Stimme geben.\n\nEs wäre eine Schande, neben Euch oder diesem Trottel Yoon Dinge anzubauen.\n\nUnd jetzt erlaubt mir, mich um meine eigenen Probleme zu kümmern. Jemand Bösartiges hat meine Preisyaks aus ihrem Pferch herausgelassen und jetzt laufen sie nordwestlich von Halbhügel frei herum.\n\nWenn ich doch nur meine Yaks zurückbekäme, könnte ich nachts wieder schlafen.", sourceObjective = "Bringt 5 entlaufene Wollyaks zu Bauer Fungs Yakpferch am nördlichsten Ende des Grünen Gürtels zurück.", completion = "<Bauer Fung starrt Euch mit heruntergeklappter Kinnlade an.>\n\nIch... Ich kann nicht fassen... dass IHR all meine erstklassigen Wollyaks wieder einfangen konntet!\n\nWisst Ihr... wisst Ihr überhaupt, wie viel mir das bedeutet?\n\nMeine Familie kennt sich nur mit zwei Dingen aus: dem Anbau gigantischen Gemüses und der Yakzucht.\n\nDie Wollyaks, die Ihr da seht, sind das Ergebnis der Arbeit von Generationen.\n\nIhr habt das Erbe meiner Familie gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30519] = { id = 30519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nanas Stimme I: Nanas Geheimrezept", description = "Die nächste Stimme, die wir brauchen, ist die von Nana Lehmkrall. Sie ist Haohans Großmutter und war schon Ackerbäuerin, bevor Ihr und ich auf die Welt kamen!\n\nSie arbeitet noch immer im Haus der Ackerbauern in Halbhügel. Warum besucht Ihr sie nicht?", sourceObjective = "Sprecht mit Nana Lehmkrall in Halbhügel im Tal der Vier Winde.", completion = "Ja, Nana Lehmkrall... das bin ich. Ich bin zwar alt, aber mit meinem Gedächtnis ist noch alles in Ordnung. Bei dem alten Herrn Weißbart ist das allerdings eine ganz andere Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[30521] = { id = 30521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohans Stimme I: Einbruch in der Hütte", description = "Das wird nicht einfach, {name}.\n\nDie letzte Stimme, die wir brauchen, ist die von Haohan Lehmkrall, dem Vorsitzenden des Bundes der Ackerbauern.\n\nIch weiß, dass er uns zu Beginn nicht wohlgesinnt war. Aber wir haben schon so viel über die Landwirtschaft gelernt, dass er sich sicher umstimmen lassen wird!\n\nBitte sprecht mit ihm. Ihr könnt doch überzeugend auftreten, oder?", sourceObjective = "Sprecht mit Haohan Lehmkrall im Kernland oder auf dem Halbhügelmarkt im Tal der Vier Winde.", completion = "Was wünscht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[30522] = { id = 30522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohans Stimme II: Die wahren Schuldigen", description = "Was macht IHR denn hier, Stadtpfote?\n\nAlso, ich habe schon alle Hände voll zu tun mit dem Einbruch in die Hütte im Westen. Einige Mistkerle sind dort mitten in der Nacht eingebrochen und haben sie geplündert.\n\nIch muss mich um verschwundene Samen, zerbrochene Werkzeuge und angebissenes Zubehör kümmern.\n\nIch werde es auf die Liste mit meinen anderen Sorgen setzen: ein gestohlener voll mit Melonen beladener Wagen; eine defekte Wasserpumpe; Ungeziefer, das mir die Ernte ruiniert...\n\nWenn ich all dem nur auf den Grund gehen könnte!", sourceObjective = "Untersucht 8 verdächtige Fußspuren.", completion = "Hmmm, tut mir leid, hören zu müssen, dass Haohan bis zum Hals in der Klemme steckt. Danke, dass Ihr mir Bescheid sagt. Vielleicht können wir ihm helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30523] = { id = 30523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hof pflegen II: Der zerbrochene Wagen", description = "Hey {name}. Seit meinem ersten Tag hier habe ich mir immer diesen Wagen angeschaut. Der ist ganz schön ramponiert, findet Ihr nicht?\n\nIch hab' in der Stadt gehört, dass Fischi Rohrroder gut mit Werkzeugen umgehen kann. Vielleicht kann sie ihn ja reparieren. Dann könnten wir dieses Stück Land in Ackerland verwandeln.\n\nWollt Ihr nicht mal mit ihr sprechen und sie fragen, ob sie diese Arbeit erledigen will?", sourceObjective = "Sprecht mit Fischi Rohrroder am Rohrkolbensee oder auf dem Halbhügelmarkt im Tal der Vier Winde.", completion = "Braucht Ihr bei irgendwas Hilfe? Da seid Ihr bei mir an der richtigen Adresse!", sourceObjectiveStatus = "unverified-source-field" }
quests[30524] = { id = 30524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hof pflegen II: Klopf auf Holz", description = "Klar! Ich kenne den Wagen, von dem Ihr erzählt habt!\n\nDen kann ich sofort reparieren, aber dafür brauche ich Holz.\n\nUnten auf dem Seegrund gibt es jede Menge davon. Wenn Ihr es denn gleich rausfischen könntet? Ha ha, fischen für Fischi - verstanden? Oh, manchmal könnt ich mich über mich selbst totlachen.\n\nAber bringt mir einfach etwas von dem Holz. Dann kann ich gleich anfangen!", sourceObjective = "Sammelt 100 gewachste Bretter zusammen.", progress = "Dieser See ist wirklich voller Schätze. Man muss nur wissen, wonach man suchen soll.", completion = "Ja! Das ist genau das richtige Holz. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30525] = { id = 30525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohans Stimme III: Pures Gift", description = "So, {name}. Das ist die Gelegenheit für uns!\n\nLehmkralls Hof steckt in großen Schwierigkeiten. Diese Ho-zen aus den Bergen kommen des Nachts ins Tal, verwüsten seine Pflanzen und tun sich an seiner schwer verdienten Ernte gütlich.\n\nWir müssen sie ein für alle Mal loswerden, und ich weiß auch schon wie.\n\nMein Großvater hat mir seinerzeit gezeigt, wie man ein Verwundungsgift für das Ungeziefer auf der Farm mischt.\n\nDie Hauptzutaten dafür sind in den Höhlen der Shed-Ling im Norden zu finden.\n\nSchaut nicht so besorgt drein, {name}! Ich bin ziemlich sicher, dass es funktionieren wird.", sourceObjective = "Sammelt 1 Blutblüte, 1 Höhlenlilie, 1 Geisterkappe und 1 Veilchenflechte ein.", progress = "Auf die Ho-zen wartet eine große Überraschung!", completion = "Ihr habt die Zutaten? Gute Arbeit!\n\nUnd jetzt muss ich dieses Mittel herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30526] = { id = 30526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsam und allein", description = "Der hungrige und ausgemergelte Hund jault herzzerreißend und versucht kurz, mit dem Schwanz zu wedeln.\n\nEr sieht aus, als könne er eine gute Mahlzeit vertragen.", sourceObjective = "Besorgt 20 köstliche T-Bone-Steaks von den Himmelsweitenmushan auf der Himmelsweite im Tal der Vier Winde.", progress = "Die Augen des Hundes leuchten auf. Er scheint Euch wiederzuerkennen.", completion = "Beim Anblick der saftigen Steaks stellen sich die Ohren des Hundes steil nach oben.\n\nSobald Ihr sie hingeworfen habt, fängt der Hund gierig zu fressen an.", sourceObjectiveStatus = "unverified-source-field" }
quests[30527] = { id = 30527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohans Stimme IV: Melonenmanie", description = "Nun, zufällig weiß ich, dass diese Ho-zen aus den Bergen süße Melonen lieben.\n\nHaohans letzte Melonenernte wurde gestohlen, also werden wir unsere eigenen züchten müssen.\n\nSobald wir sie ernten können, werden wir den Anführer dieser verdammten Ho-zen damit aus seiner Höhle locken!", sourceObjective = "Pflanzt und erntet 4 Streifenmelonen und bringt dann 20 Streifenmelonen zu Bauer Yoon.\n\nIhr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben. Nach dem Beackern und Pflegen Eurer Pflanze müsst Ihr bis zum nächsten Tag warten, um reife Streifenmelonen zu ernten.", progress = "Wir sehen lieber zu, dass wir ein paar anständige Melonen züchten, {name}. Diese hinterhältigen Ho-zen mögen nur die süßesten Melonen.", completion = "Wow, {name}! Wenn das keine dicken Melonen sind. Solche anzubauen ist kein Kinderspiel - ich sollte es wissen, denn ich habe es versucht! \n\nIch weiß nicht, wie ich diesen Betrieb ohne Euch schmeißen sollte, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30528] = { id = 30528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohans Stimme V: Häuptling Yip-Yip", description = "Seid Ihr bereit für den letzten Teil des Plans?\n\nDie Ho-zen oben in Kunzen werden von einem grimmigen Häuptling namens Yip-Yip angeführt. Man sagt, dass er fast vollkommen unempfindlich gegen Schmerzen sei.\n\nIch habe die Melonen mit einem Gift injiziert, also versucht nicht, sie anzuknabbern!\n\nWenn Ihr seine Aufmerksamkeit erregt habt, werft die Melonen. Yip-Yip wird einer so süßen Streifenmelone nicht widerstehen können.\n\nWenn er hineinbeißt, wird er vorübergehend geschwächt sein, sodass Ihr Gelegenheit zum Angriff habt.", sourceObjective = "Tötet Häuptling Yip-Yip bei der Kunzen-Höhle im Nordwesten.", completion = "Der Ho-zen-Häuptling ist tot? Unser Plan hat funktioniert, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30529] = { id = 30529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hof pflegen III: Der bemooste Felsbrocken", description = "Nachdem wir nun offiziell Mitglieder des Bundes der Ackerbauern sind, hat uns Herr Lehmkrall angeboten, uns beim Wegräumen dieses großen alten Felsens mitten in unserem Feld zu helfen.\n\nWenn dieser Stein dann weg ist, habe ich etwas Besonderes vor.\n\nLauft schnell runter und lasst ihn wissen, dass wir bereit sind.", sourceObjective = "Sprecht mit Haohan Lehmkrall im Kernland oder auf dem Halbhügelmarkt im Tal der Vier Winde.", completion = "Yoon braucht nachbarschaftliche Hilfe, wie? Dem kommen wir gerne nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[30534] = { id = 30534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hofhelfer gesucht", description = "Trotz all Eurer Bemühungen türmt sich die Arbeit auf dem Hof immer höher.\n\nVielleicht könnt Ihr ja Eure Freunde fragen, ob jemand von ihnen Lust hat, auf dem Gehöft Sonnensang zu arbeiten.", sourceObjective = "Sprecht Euren besten Freund oder Eure beste Freundin an, ob er oder sie Lust hat, auf dem Gehöft Sonnensang zu arbeiten.", completion = "Die Talismane am Schrein klimpern leise im Wind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30535] = { id = 30535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agrikultur I: Samen", description = "Das Wichtigste zuerst! Ich werde hier eine Menge Hilfe benötigen.\n\nWenn wir Partner sein wollen, müsst Ihr lernen, wie man Pflanzen erntet. Und wenn man Pflanzen ernten will, muss man erst einmal Saat ausbringen!\n\nAlso, da gibt es einen Händler namens... Glühfell? Nein, der heißt... Fellgrün? Nein, auch nicht richtig...\n\nGrünfeld! Das war der Name! Bei ihm kann man Saatgut erwerben.\n\nGrünfeld hat einen Stand drüben auf dem Halbhügelmarkt, gleich südöstlich von hier. Geht zu ihm, um ein paar Gemüsesamen zu holen.", sourceObjective = "Sprecht mit Händler Grünfeld auf dem Halbhügelmarkt und erwerbt ein Päckchen mit Grünkohlsamen.", progress = "Alles klar, Partner? Habt Ihr die Samen von Grönkelt bekommen?\n\nÄhh ... Ich meine: Grünfeld.", completion = "Er hat mir zugewinkt! Und er hat Euch sogar die erste Packung Samen umsonst gegeben?\n\nWas für ein netter Kerl!\n\nIhr leistet wirklich gute Arbeit bis jetzt. Hier, für Euch... etwas Kohle für Kohlsamen. Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[30538] = { id = 30538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß für die Kleinen", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", sourceObjective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30565] = { id = 30565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter Vorteil", description = "In letzter Zeit scheint vermehrt alles zu unseren Gunsten zu laufen, {name}. Auf einer Erkundungstour bin ich auf dieses Schätzchen gestoßen.\n\n<Sully deutet auf die Balliste zu seiner Rechten.>\n\nDas Problem ist, dass es eigentlich zwei sind, die andere aber in ihre Einzelteile zerlegt ist. Ich hätte sie inzwischen längst zusammengesetzt, wenn mir diese lästigen Grimmblicke nicht einige Getriebeteile und Bolzen abgenommen hätten.\n\nHey, Ihr scheint gut mit den Einheimischen umgehen zu können. Würdet Ihr dem alten Sully vielleicht ein wenig zur Hand gehen?", sourceObjective = "Nehmt den Ho-zen-Wegelagerern im Osten die verschwundenen Getriebeteile mit Wasserschaden und rostigen Klemmbolzen wieder ab.", progress = "Habt Ihr die verschwundenen Getriebeteile und Bolzen gefunden?", completion = "Sie sind zwar nicht im besten Zustand, müssen aber reichen.\n\n<Sully tätschelt die zerlegte Balliste.>\n\nIch bringe sie in null Komma nichts auf Vordermann, Ihr werdet schon sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30567] = { id = 30567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blanches Hammerbräu", description = "Riecht Ihr es in der Luft? Ein Sturm braut sich zusammen. Da braue ich doch gleich mit!\n\nKommt hoch auf den Hügel, wenn der Sturm da ist, dann brauen wir gemeinsam ein Fässchen meines berühmtesten Gebräus. Kann ich auf Eure Hilfe zählen?", sourceObjective = "Schließt das Szenario Ein Sturm braut sich zusammen ab.", completion = "Gar nicht mal so schlecht, {class}! Wir haben das Kloster gerettet und es ist immer noch ein halbes Fass übrig.\n\nDanke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[30568] = { id = 30568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ziel entgegen", description = "Willkommen zurück, {name}! Anscheinend haben die Jinyu unsere Ausbildung besser umgesetzt als gedacht. Unsere Vorbereitungen sind fast abgeschlossen.\n\nIch brauche jemanden, der nach Amber, Karasshi dem Draufgäger und Mishka sieht. Fragt sie, ob sie Hilfe bei der Ausbildung brauchen.\n\nKarasshi und Mishka befinden sich hier, im Dorf der Perflossen. Amber bildet Rekruten in den Schlingschwanzgruben im Nordwesten aus.", sourceObjective = "Sprecht mit Karasshi dem Draufgänger, Amber Kearnen und Mishka.", completion = "Sehr beeindruckend, {name}. Wir können bald aufbrechen. Mit unseren Verbündeten an unserer Seite wird uns niemand besiegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30569] = { id = 30569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger auf dem Bauernhof", description = "Ich... Ich bin von Bauer Chows Hof südöstlich von hier entkommen. Er wurde von Yaungol eingenommen, aber der alte Mann und seine Frau wollen einfach nicht aufgeben!\n\nBitte, geht dorthin und unterstützt sie. Wenn Ihr das tut, wird er vielleicht ein paar Leute hierher schicken, die dabei helfen, Nahrung für die neue Stadt anzubauen.", sourceObjective = "Sprecht mit dem Bauern Chow auf dem Bauernhof der Chows am Kun-Lai-Gipfel.", completion = "Was für ein willkommener Anblick Ihr seid, {class}.\n\nUnd ich will der Allianz wirklich gerne helfen. Aber zuerst müsst Ihr dafür sorgen, dass ich meinen Hof zurückbekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[30570] = { id = 30570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger auf dem Bauernhof", description = "Ich... Ich bin von Bauer Chows Hof südöstlich von hier entkommen. Er wurde von Yaungol eingenommen, aber der alte Mann und seine Frau wollen einfach nicht aufgeben!\n\nBitte, geht dorthin und unterstützt sie. Wenn Ihr das tut, wird er vielleicht ein paar Leute hierher schicken, die dabei helfen, Nahrung für die neue Stadt anzubauen.", sourceObjective = "Sprecht mit dem Bauern Chow auf dem Bauernhof der Chows am Kun-Lai-Gipfel.", completion = "Was für ein willkommener Anblick Ihr seid, {class}.\n\nUnd ich will der Horde wirklich gerne helfen. Aber zuerst müsst Ihr dafür sorgen, dass ich meinen Hof zurückbekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[30571] = { id = 30571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Hofhelfer", description = "Diese Ordo-Yaungol lassen meine Hofhelfer sich zu Tode schuften! Das darf nicht geschehen.\n\nIch bitte Euch, {class}: Rettet sie, bevor es zu spät ist.", sourceObjective = "Befreit 12 Bauernhofsklaven, indem Ihr die Aufseher von Ordo tötet.", completion = "Ihr seid ja wirklich zu etwas zu gebrauchen!\n\nObwohl... Ich glaube, es ist nicht fair, diese Arbeiter dazu zu zwingen, bei uns zu bleiben. Wir haben ja nicht mehr so viel Arbeit für sie...", sourceObjectiveStatus = "unverified-source-field" }
quests[30575] = { id = 30575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibt sie zusammen", description = "Beweglichkeit wird von größter Bedeutung sein, wenn wir uns in diesem neuen Land behaupten wollen. Das Problem ist nur, dass man ohne Reittiere nicht besonders beweglich ist, und... nun, wir haben nicht viele von denen hier, nicht wahr?\n\nDie hiesigen Yaks scheinen gute Reittiere abzugeben. Zumindest sagen das die hiesigen Pandaren. Warum besorgt Ihr nicht ein paar für uns?", sourceObjective = "Treibt 3 Yaks der Wilden Ebenen zusammen und bringt sie zur Westwindruhestätte.", completion = "Diese Yaks sollten ausreichen. Gut gemacht, {name}. Diese Situation gefällt mir schon viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[30581] = { id = 30581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eintopf braucht Topf!", description = "Na klar, ich helfe Euch gerne. Aber auch wir müssen etwas essen! Ich habe noch nicht einmal einen Kochtopf! Ganz zu schweigen von Zutaten, die ich hinein tun könnte!\n\nHier ist eine Liste der Dinge, die ich brauche. Und jetzt macht Euch auf!", sourceObjective = "Besorgt 12-mal Wurzelgemüse und 1 gusseisernen Topf.", progress = "Habt Ihr alle Sachen von der Liste?", completion = "Na, da haben wir es doch. Das sollte wirklich mehr als ausreichend sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30582] = { id = 30582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verschiedene Frau Moschuspranke", description = "Auf diesem schon reichlich abgenutzten Schmuckstück befinden sich zahlreiche Liebesbekundungen der verstorbenen Frau Moschuspranke.\n\nVielleicht hätte Lao das Schmuckstück seiner Frau gerne zurück.", sourceObjective = "Bringt Lao MoschusprankeMoschusprankes Andenken zurück.", progress = "Oh, was habt Ihr denn da?!", completion = "Einen wahren Wert erkennt man erst durch einen Verlust. Ich habe meine Frau schon vor ein paar Jahreszeiten verloren, aber heute ist der Tag, an dem mich ihr Lächeln am meisten trösten würde.\n\nZumindest muss sie nicht sehen, was diese Yaungol auf ihrem geliebten Hof angerichtet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30583] = { id = 30583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blauer Zwerg braucht dringend Nahrung", description = "He da!\n\nWir brauchen dringend was zu essen, wenn wir hier für längere Zeit überleben wollen!\n\nIhr wisst es vielleicht nicht, aber ich bin selbst so etwas wie ein Koch. Warum geht Ihr nicht los und holt uns ein paar fleischige Brocken? Dann koche ich daraus etwas, und wir haben wochenlang zu essen! Oder wenigstens tagelang.", sourceObjective = "Besorgt 160 Kun-Lai-Fleischbrocken.", progress = "Nun... habt Ihr mein Fleisch?", completion = "Gute Arbeit! Ich sag' Euch, diese Kun-Lai-Fleischbrocken sind 1a Qualität!", sourceObjectiveStatus = "unverified-source-field" }
quests[30584] = { id = 30584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schockierend!", description = "Habt Ihr schon einmal frischen Dojaniaal probiert, {name}? Nein?\n\nNun, dann entgeht Euch aber einiges! Macht Euch zum Dojani im Norden auf und angelt uns ein paar von ihnen. Seid vorsichtig - diese Aale verpassen Euch einen Stromschlag, wenn Ihr nicht aufpasst!", sourceObjective = "Angelt 7 Dojaniaale aus dem Dojani in der Krasarangwildnis.", progress = "Habt Ihr es geschafft, diese Aale zu fangen?", completion = "Das sieht nach ein paar schmackhaften Aalen aus, {name}! Ich bin sicher, Ihr werdet sie lieben!", sourceObjectiveStatus = "unverified-source-field" }
quests[30585] = { id = 30585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was in der Tiefe lauert", description = "Den Legenden zufolge gibt es eine riesige Kreatur im Wald im Norden. Mein Sohn wird vermisst, und ich fürchte, er ist zu nah an ihren Unterschlupf geraten...\n\nGeht Richtung Nordwesten zu den Krasarifällen und haltet nach einem geheimnisvollen Strudel Ausschau - er ist der Schlüssel zu dem, was sich dort verbirgt. Tötet dieses üble Monster und sucht nach Hinweisen auf den Verbleib meines Sohns.", sourceObjective = "Sucht einen uralten Angelteich bei den Krasarifällen im Nordwesten und fischt dort, um die Bestie aus ihrem Versteck zu locken.", progress = "Gibt es Neuigkeiten über meinen Sohn?", completion = "Der Ring meines Sohns? Was bedeutet das?\n\n<Rassan scheint nachdenklich zu sein.>\n\nDie Situation ist hart, aber nicht hoffnungslos. Mein Sohn geht achtlos mit seinen Habseligkeiten um, also hat er den Ring vielleicht einfach in den Teich geworfen? Danke für Eure Hilfe, {name}, ich werde nicht vergessen, was für einen großen Gefallen Ihr mir erwiesen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30586] = { id = 30586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezacktes Seeohr", description = "Die Pandaren haben über Generationen hinweg in dieser Gegend gezackte Seeohren geerntet. Jetzt ist es an der Zeit, dass Ihr das Ritual erlernt.\n\nSeeohren können gleich nordöstlich von hier im Narsonggraben gefunden werden. Aber seid vorsichtig - in der Nähe sind seit Kurzem vermehrt Haie gesichtet worden.", sourceObjective = "Sammelt 9 Stück Seeohrenfleisch von gezackten Seeohren im Narsonggraben im Nordwesten.", progress = "Habt Ihr da unten Haie gesehen?", completion = "Oh! Anscheinend habt Ihr eine Menge Seeohren dort draußen gefunden. Großartige Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30587] = { id = 30587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände weg von meinen Yaks!", description = "Im Moment scheinen die Eindringlinge der Yaungol noch damit zufrieden zu sein, Yaks zu stehlen. Wenn Ihr das Gebiet näher untersucht, werdet Ihr jedoch feststellen, dass sie leicht jederzeit zur Yaksalberei weitergehen könnten.\n\nDas Ausdünnen ihrer Reihen würde den Yaungol vielleicht zeigen, dass dieses Gebiet gesichert ist.", sourceObjective = "Tötet 9 Räuber der Burilgi auf dem Gehöft Moschuspranke.", completion = "Ich bin Euch wirklich sehr dankbar, dass Ihr ein paar dieser Yaungol für uns erledigt habt.\n\nIch hoffe, dass diese kleine Demonstration Eurer Stärke reichen wird, um sie davon abzuhalten, zu uns zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30588] = { id = 30588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischen mit blauem Auge", description = "Der Klan der Flussklingen-Saurok greift eine unserer hiesigen Angelexpeditionen an! Sie brauchen sofort Hilfe!\n\nRäumt bei diesen Saurok auf und helft dieser Expedition, sicher zurückzukehren!", sourceObjective = "Tötet 8 Strandräuber der Flussklingen bei der Anglerexpedition westlich von der Anlegestelle der Angler.", completion = "Die Expedition ist in Sicherheit. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30589] = { id = 30589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wrack abwracken", description = "Um das Allianzschiff loszubekommen, müssen wir zuerst unseren Ingenieur finden. Unsere Wege haben sich getrennt, als wir aus dem Wrack geflohen sind.\n\nIhr solltet ihn irgendwo im Wald westlich von hier finden können. Sagt ihm, dass Korga Euch geschickt hat, und er wird seinen Posten wieder antreten.", sourceObjective = "Sprecht mit Makael Bay im Pei-Wu-Wald.", sourceObjectiveStatus = "unverified-source-field" }
quests[30590] = { id = 30590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht! Explosiv!", description = "Wir können Euch dabei helfen, das Schiff freizubekommen, aber um das zu bewerkstelligen, brauchen wir mehr von dem Sprengstoff, den wir uns von der Allianz zurückholen wollten.\n\nIch habe die Besatzung angewiesen, sich so viel Sprengstoff wie möglich zu schnappen, bevor wir uns zurückgezogen haben. Wenn Ihr die Trümmerteile und Leichname südlich von hier durchsucht, solltet Ihr einige Sprengstoffpakete finden können - zumindest die, die noch nicht in die Luft gegangen sind.\n\nBringt mir genug davon und ich werde Euch etwas Schönes zusammenbasteln...", sourceObjective = "Bergt 6 Sprengsätze.", sourceObjectiveStatus = "unverified-source-field" }
quests[30591] = { id = 30591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Jäger zum Gejagten", description = "Der Wald ist deutlich gefährlicher geworden, seit Shen-zin Su begonnen hat zu beben. Die Tiger sind unruhig und haben begonnen, die Flüchtlinge anzugreifen - auch auf mich haben sie es nun abgesehen.\n\nFalls diese verletzten und geschwächten Überlebenden es bis hierher zur Hütte schaffen sollen, dann müssen wir ihnen den Weg freimachen.", sourceObjective = "Tötet 9 Pei-Wu-Tiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[30592] = { id = 30592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jutepfad: Zum Basislager am Kota", description = "Heute ist kein guter Tag für Grummel. Die Ho-zen haben angefangen zu plündern! Greifen unsere Versorgungslinie zum Schlangenrücken an.\n\nKönnt Ihr helfen? Wir sind keine Kämpfer. Wir sind Grummel. Das Glück lacht denen, die Grummeln helfen.\n\nGeht mit einer Gruppe Grummel zur Zwischenstation des Jutepfads. Beschützt sie. Sorgt dafür, dass wenigstens ein Grummel überlebt.\n\nGrummel geben Belohnung. Grummel geben immer Belohnung.", sourceObjective = "Beschützt eine Gruppe Grummel auf dem Weg zur Zwischenstation des Jutepfads. Mindestens ein Grummel muss überleben.\n\nWenn Ihr die Grummel verliert, könnt Ihr den Jutepfad absuchen oder nach Einfass zurückkehren und warten, bis die nächste Gruppe aufbricht.", progress = "Viel Glück für Freunde der Grummel.", completion = "Habt Dank. Ich wünsche Euch Glück, Freund der Grummel. Aber der Weg zum Schlangenrücken ist noch nicht sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[30593] = { id = 30593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Leben zu Asche", description = "Der Admiral erwartet, dass ich mich um ein großes Problem kümmere, aber meine Spezialität ist das Heilen und nicht das Kämpfen!\n\nDie Pandaren im Lager haben berichtet, dass im Nordosten, in Mogujia, irgendetwas die Statuen zu Leben erwachen lässt.\n\nKönntet Ihr mir in dieser Angelegenheit aushelfen, {name}? Im Augenblick können wir uns einen Kampf mit dieser Armee Statuen einfach nicht leisten.", sourceObjective = "Zerstört 14 Terrakottakrieger oder Terrakottawächter.", completion = "Na also! Sieht so aus, als ob wir uns nicht länger den Kopf über einen Haufen Statuen zerbrechen müssen. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30594] = { id = 30594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Leben zu Asche", description = "Ich habe hier so viel zu tun, {name}. Ich könnte Eure Hilfe gebrauchen.\n\nIm Nordwesten gibt es einen Ort, den die Pandaren Mogujia nennen. Und durch irgendetwas dort werden die Statuen zum Leben erweckt. Unsere Pandarenfreunde hier sind deswegen wirklich beunruhigt.\n\nWenn sich nicht bald jemand darum kümmert, bekommen wir ein echtes Problem. Wir sind gerade erst angekommen. Wir können es uns gerade nicht erlauben, einen Krieg gegen eine Armee von Statuen zu führen.", sourceObjective = "Zerstört 14 Terrakottakrieger oder Terrakottawächter.", completion = "Oh, Ihr habt Euch der Statuen angenommen? Gute Arbeit. Hier ist etwas für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
